:root{
  --ink:#f7f1e3;
  --muted:#a9a094;
  --lava:#7dff3c;
  --lava-deep:#3cff8a;
  --ember:#ff7a1a;
  --blue:#38d6ff;
  --red:#ff4d63;
  --gold:#ffd166;
  --panel:rgba(9,12,13,.82);
  --safe-t:env(safe-area-inset-top,0px);
  --safe-r:env(safe-area-inset-right,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; background:#050708; color:var(--ink); overflow:hidden;
  font-family:"Bahnschrift","Arial Narrow",Arial,system-ui,sans-serif;
  -webkit-tap-highlight-color:transparent;
  overscroll-behavior:none;
}
#game{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none;outline:none}
#safe-probe{
  position:fixed;inset:0;pointer-events:none;visibility:hidden;
  padding:env(safe-area-inset-top,0px) env(safe-area-inset-right,0px) env(safe-area-inset-bottom,0px) env(safe-area-inset-left,0px);
}

/* ---------- overlays ---------- */
.overlay{
  position:fixed; inset:0; z-index:10; display:flex; align-items:center; justify-content:center;
  padding:calc(14px + var(--safe-t)) calc(16px + var(--safe-r)) calc(14px + var(--safe-b)) calc(16px + var(--safe-l));
  transition:opacity .38s ease, visibility .38s;
}
.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
#menu{
  overflow-y:auto; overscroll-behavior:contain;
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(125,255,60,.10), transparent 55%),
    radial-gradient(100% 70% at 50% 115%, rgba(255,92,20,.13), transparent 60%),
    linear-gradient(180deg, rgba(3,5,6,.72) 0%, rgba(3,5,6,.86) 48%, rgba(3,5,6,.94) 100%);
  backdrop-filter:blur(2.5px) saturate(.9);
}
.menu-glow{
  position:fixed;inset:0;pointer-events:none;
  background:repeating-linear-gradient(180deg, rgba(255,255,255,.022) 0 1px, transparent 1px 4px);
  mix-blend-mode:overlay;
}
.menu-inner{
  position:relative; width:min(1120px,100%); margin:auto; display:flex; flex-direction:column; gap:16px;
  padding:8px 0 4px;
}
.hero{text-align:center; padding-top:2px}
