.play.small{min-width:200px;padding:12px 26px}
.mobile-hint{display:none;font-size:10px;letter-spacing:.08em;color:#8f8678}
.menu-foot{display:flex;flex-wrap:wrap;justify-content:center;gap:6px 15px;color:#8a8174;font-size:10px;letter-spacing:.09em;padding-bottom:4px}
kbd{font-family:inherit;font-weight:900;font-size:9px;color:#ddd2be;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.13);border-radius:4px;padding:2px 5px;margin-right:2px}

/* result */
.result{background:radial-gradient(80% 80% at 50% 50%,rgba(4,7,6,.72),rgba(2,3,3,.94));backdrop-filter:blur(4px)}
.result-inner{text-align:center;max-width:560px;padding:28px 24px;border-radius:20px;
  background:linear-gradient(170deg,rgba(24,28,26,.9),rgba(7,9,8,.95));border:1px solid rgba(255,255,255,.12);
  box-shadow:0 30px 80px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.1)}
.result h2{font-family:"Arial Black",Impact,sans-serif;font-style:italic;font-size:clamp(38px,8vw,64px);margin:8px 0 2px;line-height:.95;
  background:linear-gradient(180deg,#fff6dc,#ffd166 50%,#ff7a1a);-webkit-background-clip:text;background-clip:text;color:transparent}
.result h2.lose{background:linear-gradient(180deg,#ffe7e9,#ff7a8a 50%,#a8142b);-webkit-background-clip:text;background-clip:text;color:transparent}
.result-score{font-family:"Arial Black",Impact,sans-serif;font-size:30px;letter-spacing:.12em;color:#e9dfcb;margin:2px 0 8px}
.result-sub{color:#a59b8b;font-size:12px;margin:0 0 18px;letter-spacing:.06em}
.result-actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;align-items:center}
.ghost{all:unset;cursor:pointer;padding:12px 20px;border-radius:12px;border:1px solid rgba(255,255,255,.2);color:#e3d9c8;font-size:11px;font-weight:900;letter-spacing:.14em}
.ghost:hover{border-color:rgba(255,255,255,.45);background:rgba(255,255,255,.05)}

@media (max-width:720px){
  .menu-inner{gap:12px;padding-top:0}
  h1{font-size:clamp(48px,16vw,74px)}
  .roster{grid-template-columns:repeat(4,1fr);gap:6px}
  .card{padding:5px 5px 7px;border-radius:11px}
  .card .chip{top:9px;right:9px;font-size:6.5px;padding:2px 4px}
  .card .cname{font-size:12px;margin-top:3px}
  .card .ctitle{display:none}
  .weapon-card{padding:7px 9px;gap:7px}
  .weapon-card p{display:none}
  .weapon-card b{font-size:8.5px;letter-spacing:.11em}
  .wicon{flex-basis:27px;width:27px;height:27px;border-radius:8px}
  .egg-icon i{width:12px;height:16px}
  .plume-icon i{width:20px;height:7px}
  .play{min-width:min(320px,88vw);padding:13px 28px 11px}
  .play-main{font-size:23px}
  .mobile-hint{display:block;text-align:center}
  .menu-foot{display:none}
  .tagline{font-size:11px}
  .section-label{font-size:8.5px}
}
@media (max-height:640px) and (orientation:landscape){
  .hero h1{font-size:44px}
  .tagline{display:none}
  .weapons{display:none}
  .menu-inner{gap:8px}
  .card .portrait{max-height:90px}
}

// Tiny WebAudio synth — no assets, no network.
class SfxEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.last = new Map();
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return this.ctx;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.34;
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.knee.value = 12;
      comp.ratio.value = 8;
      this.master.connect(comp);
      comp.connect(this.ctx.destination);
      this.noise = this.makeNoise();
    } catch { this.ctx = null; }
    return this.ctx;
  }

  makeNoise() {
    const len = Math.floor(this.ctx.sampleRate * 1.2);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  gate(name, ms) {
    const now = performance.now();
    if (now - (this.last.get(name) || 0) < ms) return false;
    this.last.set(name, now);
    return true;
  }

  tone(freq, dur, type = 'sine', vol = 0.2, slide = 0, delay = 0) {
    const ctx = this.ensure();
    if (!ctx || this.muted) return;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(24, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  noiseBurst(dur, vol, freq, q = 1, type = 'bandpass', delay = 0) {
    const ctx = this.ensure();
    if (!ctx || this.muted) return;
    const t = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.playbackRate.value = 0.8 + Math.random() * 0.4;
    const f = ctx.createBiquadFilter();
    f.type = type; f.frequency.value = freq; f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t, Math.random() * 0.4); src.stop(t + dur + 0.02);
  }

  egg() {
    if (!this.gate('egg', 45)) return;
    this.tone(150, 0.16, 'triangle', 0.14, -60);
    this.noiseBurst(0.1, 0.09, 900, 1.6);
  }
  splat() {
    if (!this.gate('splat', 40)) return;
    this.noiseBurst(0.32, 0.16, 420, 0.8, 'lowpass');
    this.tone(70, 0.22, 'sine', 0.12, -30);
  }
  plume() {
    if (!this.gate('plume', 40)) return;
    this.tone(880, 0.18, 'sawtooth', 0.06, 900);
    this.noiseBurst(0.12, 0.08, 2600, 2.4);
  }
  hit() {
    if (!this.gate('hit', 35)) return;
    this.tone(220, 0.07, 'square', 0.07, -90);
    this.noiseBurst(0.06, 0.08, 1500, 1.2);
  }
  dash() {
    if (!this.gate('dash', 80)) return;
    this.noiseBurst(0.28, 0.13, 700, 0.7, 'bandpass');
    this.tone(320, 0.18, 'sine', 0.05, 360);
  }
  beam() {
    this.tone(120, 0.5, 'sawtooth', 0.18, 900);
    this.tone(1400, 0.35, 'square', 0.05, -1100);
    this.noiseBurst(0.5, 0.16, 2200, 0.7);
  }
  kill() {
    this.tone(90, 0.4, 'triangle', 0.2, -50);
    this.tone(880, 0.18, 'square', 0.05, 400, 0.03);
    this.noiseBurst(0.25, 0.1, 500, 0.7, 'lowpass');
  }
  respawn() {
    this.tone(320, 0.14, 'sine', 0.08, 320);
    this.tone(640, 0.18, 'sine', 0.06, 320, 0.1);
  }
  ui() {
    this.tone(520, 0.06, 'square', 0.05, 120);
  }
  win() {
    [392, 523, 659, 784].forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.12, 0, i * 0.11));
  }
  lose() {
    [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.4, 'triangle', 0.1, 0, i * 0.14));
  }
  toggle() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.34;
    if (!this.muted) this.ui();
    return this.muted;
  }
}

