import { WORLD, ROLE, TEAM, TAU } from './roster.js';

/* ------------------------------------------------------------------ */
/* helpers                                                             */
/* ------------------------------------------------------------------ */
export function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
export function lerp(a, b, t) { return a + (b - a) * t; }

function rr(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.arcTo(x + w, y, x + w, y + h, rad);
  ctx.arcTo(x + w, y + h, x, y + h, rad);
  ctx.arcTo(x, y + h, x, y, rad);
  ctx.arcTo(x, y, x + w, y, rad);
  ctx.closePath();
}

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shadowEllipse(ctx, x, y, rx, ry, alpha = 0.5) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* static arena (pre-rendered once)                                    */
/* ------------------------------------------------------------------ */
const rand = mulberry32(20261105);
const TILES = [];
for (let row = 0; row < 11; row++) {
  for (let col = 0; col < 18; col++) {
    const x = 120 + col * 76 + (row % 2 ? 4 : 0);
    const y = 112 + row * 71;
    TILES.push({ x, y, w: 70, h: 65, shade: rand(), rot: (rand() - 0.5) * 0.02 });
  }
}
const CRACKS = [];
for (let i = 0; i < 22; i++) {
  const pts = [];
  let x = 160 + rand() * 1280;
  let y = 150 + rand() * 700;
  let a = rand() * TAU;
  const n = 3 + Math.floor(rand() * 5);
  for (let j = 0; j < n; j++) {
    pts.push([x, y]);
    a += (rand() - 0.5) * 1.5;
    x += Math.cos(a) * (24 + rand() * 46);
    y += Math.sin(a) * (20 + rand() * 30);
  }
  CRACKS.push({ pts, glow: 0.3 + rand() * 0.5 });
}
const CROWD = [];
for (let i = 0; i < 130; i++) {
  CROWD.push({
    x: 120 + rand() * 1360,
    y: rand() < 0.5 ? 84 + rand() * 22 : 900 + rand() * 22,
    s: 2 + rand() * 3,
    a: 0.12 + rand() * 0.3,
    eye: rand() < 0.12
  });
}
const EMBERS = [];
for (let i = 0; i < 34; i++) {
  EMBERS.push({
    x: 60 + rand() * 1480,
    y: rand() * 1000,
    s: 0.8 + rand() * 2.2,
    sp: 9 + rand() * 26,
    ph: rand() * TAU,
    drift: 8 + rand() * 18
  });
}
const RUNES = [];
for (let i = 0; i < 26; i++) {
  const a = (i / 26) * TAU;
  RUNES.push({ a, len: 6 + rand() * 12, w: 1 + rand() * 1.5 });
}

let arenaLayer = null;

function buildArena() {
  const c = document.createElement('canvas');
  c.width = WORLD.w; c.height = WORLD.h;
  const x = c.getContext('2d');

  // deep background
  const bg = x.createRadialGradient(800, 500, 120, 800, 500, 1000);
  bg.addColorStop(0, '#12191a');
  bg.addColorStop(0.55, '#0a0e10');
  bg.addColorStop(1, '#040606');
  x.fillStyle = bg; x.fillRect(0, 0, WORLD.w, WORLD.h);

  // outer glow under platform
  const halo = x.createRadialGradient(800, 500, 380, 800, 500, 850);
  halo.addColorStop(0, 'rgba(88,255,88,0.05)');
  halo.addColorStop(0.6, 'rgba(40,160,90,0.035)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = halo; x.fillRect(0, 0, WORLD.w, WORLD.h);

  // platform
  x.save();
  x.shadowColor = 'rgba(0,0,0,0.85)';
  x.shadowBlur = 60;
  x.shadowOffsetY = 26;
  rr(x, 62, 62, 1476, 876, 74);
  x.fillStyle = '#14181a'; x.fill();
  x.restore();

  const plat = x.createLinearGradient(0, 62, 0, 938);
  plat.addColorStop(0, '#242a2b');
  plat.addColorStop(0.5, '#161b1c');
  plat.addColorStop(1, '#0e1213');
  rr(x, 62, 62, 1476, 876, 74);
  x.fillStyle = plat; x.fill();
  x.strokeStyle = 'rgba(150,190,180,0.16)'; x.lineWidth = 3; x.stroke();

  // outer rim runes
  x.save();
  x.translate(800, 500);
  for (const r of RUNES) {
    x.save();
    x.rotate(r.a);
    x.translate(0, -418);
    x.fillStyle = 'rgba(125,255,60,0.22)';
    x.fillRect(-r.w / 2, 0, r.w, r.len);
    x.restore();
  }
  x.restore();

  // crowd terraces
  for (const p of CROWD) {
    x.globalAlpha = p.a;
    x.fillStyle = p.eye ? (p.y < 500 ? '#7dff3c' : '#ff7a3c') : '#0a0c0c';
    x.beginPath();
    x.arc(p.x, p.y, p.s, 0, TAU);
    x.fill();
  }
  x.globalAlpha = 1;

  // arena floor
  x.save();
  x.shadowColor = 'rgba(0,0,0,0.9)';
  x.shadowBlur = 30;
  rr(x, 120, 110, 1360, 780, 44);
  x.fillStyle = '#171c1e'; x.fill();
  x.restore();

  const fl = x.createRadialGradient(800, 500, 60, 800, 500, 760);
  fl.addColorStop(0, '#222a2b');
  fl.addColorStop(0.55, '#171d1f');
  fl.addColorStop(1, '#0f1416');
  rr(x, 120, 110, 1360, 780, 44);
  x.fillStyle = fl; x.fill();

  // stone tiles
  x.save();
  rr(x, 120, 110, 1360, 780, 44);
  x.clip();
  for (const t of TILES) {
    x.save();
    x.translate(t.x + t.w / 2, t.y + t.h / 2);
    x.rotate(t.rot);
    x.globalAlpha = 0.5;
    const shade = 18 + Math.floor(t.shade * 14);
    x.fillStyle = `rgb(${shade},${shade + 4},${shade + 4})`;
    rr(x, -t.w / 2 + 1, -t.h / 2 + 1, t.w - 2, t.h - 2, 4);
    x.fill();
    x.globalAlpha = 0.22;
    x.strokeStyle = '#435052';
    x.lineWidth = 1;
    x.stroke();
    x.restore();
  }
  x.restore();

  // cracks (dark + green lava)
  x.save();
  rr(x, 120, 110, 1360, 780, 44);
  x.clip();
  for (const ck of CRACKS) {
    x.beginPath();
    x.moveTo(ck.pts[0][0], ck.pts[0][1]);
    for (let i = 1; i < ck.pts.length; i++) x.lineTo(ck.pts[i][0], ck.pts[i][1]);
    x.strokeStyle = 'rgba(0,0,0,0.75)'; x.lineWidth = 5; x.lineCap = 'round'; x.stroke();
    x.strokeStyle = `rgba(125,255,60,${0.16 + ck.glow * 0.2})`; x.lineWidth = 1.6; x.stroke();
    x.shadowColor = 'rgba(110,255,60,0.7)'; x.shadowBlur = 10;
    x.strokeStyle = `rgba(160,255,120,${0.08 + ck.glow * 0.12})`; x.lineWidth = 3; x.stroke();
    x.shadowBlur = 0;
  }
  x.restore();

  // arena floor border + hazard stripes
  rr(x, 120, 110, 1360, 780, 44);
  x.strokeStyle = 'rgba(125,255,60,0.18)'; x.lineWidth = 3; x.stroke();
  rr(x, 134, 124, 1332, 752, 36);
  x.strokeStyle = 'rgba(255,255,255,0.045)'; x.lineWidth = 1.5; x.stroke();

  // center emblem
  x.save();
  x.translate(800, 500);
  x.globalAlpha = 0.9;
  x.beginPath(); x.arc(0, 0, 196, 0, TAU);
  x.fillStyle = 'rgba(8,12,12,0.55)'; x.fill();
  x.lineWidth = 2; x.strokeStyle = 'rgba(125,255,60,0.2)'; x.stroke();
  x.beginPath(); x.arc(0, 0, 176, 0, TAU);
  x.strokeStyle = 'rgba(255,255,255,0.07)'; x.lineWidth = 1; x.stroke();

  // feather sun rays
  for (let i = 0; i < 16; i++) {
    x.save();
    x.rotate((i / 16) * TAU);
    x.globalAlpha = i % 2 ? 0.09 : 0.16;
    x.fillStyle = '#7dff3c';
    x.beginPath();
    x.moveTo(-9, -58); x.quadraticCurveTo(0, -168, 9, -58); x.closePath();
    x.fill();
    x.restore();
  }
  // inner eye / egg sigil
  x.beginPath(); x.arc(0, 0, 108, 0, TAU);
  x.strokeStyle = 'rgba(125,255,60,0.16)'; x.lineWidth = 2; x.stroke();
  x.save();
  x.rotate(-0.28);
  x.beginPath();
  x.ellipse(0, 0, 74, 52, 0, 0, TAU);
  x.fillStyle = 'rgba(6,9,8,0.9)'; x.fill();
  x.strokeStyle = 'rgba(125,255,60,0.3)'; x.lineWidth = 3; x.stroke();
  x.beginPath(); x.ellipse(0, 0, 26, 40, 0, 0, TAU);
  x.fillStyle = 'rgba(125,255,60,0.22)'; x.fill();
  x.beginPath(); x.ellipse(0, 0, 12, 32, 0, 0, TAU);
  x.fillStyle = 'rgba(5,10,6,0.95)'; x.fill();
  x.restore();
  x.restore();

  // chain posts
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU;
    const px = 800 + Math.cos(a) * 742;
    const py = 500 + Math.sin(a) * 462;
    x.save();
    x.translate(px, py);
    x.fillStyle = 'rgba(0,0,0,0.5)';
    x.beginPath(); x.ellipse(0, 12, 21, 8, 0, 0, TAU); x.fill();
    const pg = x.createLinearGradient(-6, -44, 6, 12);
    pg.addColorStop(0, '#5c6a6b');
    pg.addColorStop(0.5, '#2c3536');
    pg.addColorStop(1, '#171d1e');
    x.fillStyle = pg;
    rr(x, -6, -44, 12, 56, 4); x.fill();
    x.fillStyle = '#7dff3c'; x.globalAlpha = 0.35;
    x.beginPath(); x.arc(0, -46, 5, 0, TAU); x.fill();
    x.globalAlpha = 1;
    x.restore();
  }

  return c;
}

function drawBrazier(ctx, x, y, t) {
  const glow = 0.7 + Math.sin(t * 3.1 + x) * 0.15;
  const g = ctx.createRadialGradient(x, y - 20, 4, x, y - 20, 130 * glow);
  g.addColorStop(0, 'rgba(255,150,50,0.30)');
  g.addColorStop(0.45, 'rgba(255,90,20,0.10)');
  g.addColorStop(1, 'rgba(255,60,10,0)');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y - 20, 130 * glow, 0, TAU); ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.beginPath(); ctx.ellipse(0, 8, 26, 9, 0, 0, TAU); ctx.fill();
  // pole
  ctx.fillStyle = '#232a2b';
  rr(ctx, -7, -8, 14, 50, 5); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.12)'; ctx.lineWidth = 1; ctx.stroke();
  // bowl
  const bg = ctx.createLinearGradient(0, -46, 0, -6);
  bg.addColorStop(0, '#5c6668');
  bg.addColorStop(1, '#1a2021');
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-24, -34); ctx.quadraticCurveTo(0, -8, 24, -34);
  ctx.quadraticCurveTo(0, -46, -24, -34);
  ctx.fill();
  ctx.strokeStyle = 'rgba(125,255,60,0.25)'; ctx.lineWidth = 1.5; ctx.stroke();
  // flames
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 3; i++) {
    const ph = t * (4 + i) + i * 2 + x * 0.01;
    const h = 26 + Math.sin(ph) * 10 + i * 5;
    const sway = Math.sin(ph * 0.8) * 4;
    const fg = ctx.createLinearGradient(0, -38, 0, -38 - h);
    fg.addColorStop(0, 'rgba(255,240,180,0.95)');
    fg.addColorStop(0.4, 'rgba(255,150,40,0.8)');
    fg.addColorStop(1, 'rgba(255,60,10,0)');
    ctx.fillStyle = fg;
    ctx.beginPath();
    ctx.moveTo(-9 - i * 2, -34);
    ctx.quadraticCurveTo(-3 + sway, -34 - h * 0.55, sway, -34 - h);
    ctx.quadraticCurveTo(5 + sway, -34 - h * 0.5, 9 + i * 2, -34);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}

export function drawArena(ctx, t) {
  if (!arenaLayer) arenaLayer = buildArena();
  ctx.drawImage(arenaLayer, 0, 0);

  // pulsing cracks
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const ck of CRACKS) {
    ctx.globalAlpha = 0.14 + Math.sin(t * 2 + ck.glow * 9) * 0.06;
    ctx.beginPath();
    ctx.moveTo(ck.pts[0][0], ck.pts[0][1]);
    for (let i = 1; i < ck.pts.length; i++) ctx.lineTo(ck.pts[i][0], ck.pts[i][1]);
    ctx.strokeStyle = '#7dff3c';
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  ctx.restore();

  // animated runes around center
  ctx.save();
  ctx.translate(800, 500);
  ctx.rotate(t * 0.08);
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 8; i++) {
    ctx.save(); ctx.rotate((i / 8) * TAU);
    ctx.globalAlpha = 0.12 + Math.sin(t * 2 + i) * 0.05;
    ctx.fillStyle = '#7dff3c';
    ctx.fillRect(-2, -232, 4, 16);
    ctx.restore();
  }
  ctx.restore();

  drawBrazier(ctx, 208, 210, t);
  drawBrazier(ctx, 1392, 210, t);
  drawBrazier(ctx, 208, 800, t);
  drawBrazier(ctx, 1392, 800, t);

  // floating embers
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const e of EMBERS) {
    const y = ((e.y - t * e.sp) % 1040 + 1040) % 1040;
    const x = e.x + Math.sin(t * 0.6 + e.ph) * e.drift;
    const a = 0.16 + Math.sin(t * 2.2 + e.ph) * 0.1;
    ctx.globalAlpha = Math.max(0, a);
    ctx.fillStyle = e.s > 2 ? '#a6ff6c' : '#ffb35c';
    ctx.beginPath(); ctx.arc(x, y, e.s, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* champions                                                           */
/* ------------------------------------------------------------------ */
function limb(ctx, x1, y1, x2, y2, width, color) {
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
}

function drawLeg(ctx, p, hipX, step, swing, facingRight) {
  const kneeX = hipX + swing * 9;
  const kneeY = -17;
  const footX = hipX + swing * 15;
  const footY = -2;
  // muscular thigh
  limb(ctx, hipX, -35, kneeX, kneeY, 13, p.skin);
  ctx.save();
  ctx.globalAlpha = 0.35;
  limb(ctx, hipX + 2, -33, kneeX + 2, kneeY + 1, 6, p.skinLight);
  ctx.restore();
  // scaly shin
  limb(ctx, kneeX, kneeY + 1, footX, footY - 1, 8, p.beak);
  limb(ctx, kneeX - 1, kneeY + 1, footX, footY - 1, 4, p.skinDark);
  // talons
  ctx.strokeStyle = p.beak;
  ctx.lineWidth = 2.4;
  ctx.lineCap = 'round';
  const dir = facingRight ? 1 : -1;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(footX, footY);
    ctx.lineTo(footX + dir * (7 + (i === 0 ? 4 : 0)), footY + i * 4 + 1);
    ctx.stroke();
  }
  // spur
  ctx.strokeStyle = '#e9e1cb';
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(kneeX - 2, -12); ctx.lineTo(kneeX - 9, -16); ctx.stroke();
}

function drawEgg(ctx, x, y, r, seed, flash) {
  ctx.save();
  ctx.translate(x, y);
  const g = ctx.createRadialGradient(-r * 0.3, -r * 0.45, r * 0.1, 0, 0, r);
  g.addColorStop(0, '#2b332b');
  g.addColorStop(0.45, '#0b0f0b');
  g.addColorStop(1, '#020302');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, 0, r * 0.82, r, 0, 0, TAU);
  ctx.fill();
  // lava cracks
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = flash ? '#d8ffb0' : '#7dff3c';
  ctx.shadowColor = '#5cff32';
  ctx.shadowBlur = 14;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-r * 0.45, -r * 0.3);
  ctx.lineTo(-r * 0.1, -r * 0.05);
  ctx.lineTo(-r * 0.3, r * 0.35);
  ctx.moveTo(r * 0.1, -r * 0.55);
  ctx.lineTo(r * 0.18, -r * 0.15);
  ctx.lineTo(r * 0.5, r * 0.1);
  ctx.stroke();
  ctx.restore();
  ctx.restore();
}

function drawWeapon(ctx, u, p, la, hand, t) {
  const role = u.def.role;
  ctx.save();
  ctx.translate(hand.x, hand.y);
  ctx.rotate(la);
  if (role === 'brawler') {
    // gauntlet basket
    ctx.fillStyle = p.glove;
    rr(ctx, -9, -10, 22, 20, 7); ctx.fill();
    ctx.strokeStyle = p.metal; ctx.lineWidth = 2;
    rr(ctx, -9, -10, 22, 20, 7); ctx.stroke();
    ctx.fillStyle = 'rgba(125,255,60,0.18)';
    ctx.beginPath(); ctx.arc(2, 0, 14, 0, TAU); ctx.fill();
    // rivets
    ctx.fillStyle = '#c9d2cf';
    ctx.beginPath(); ctx.arc(-5, -6, 1.6, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(-5, 6, 1.6, 0, TAU); ctx.fill();
    drawEgg(ctx, 12, 0, 9.5, u.seed, u.flash > 0);
  } else {
    // obsidian feather rifle
    const L = 48;
    ctx.fillStyle = '#101617';
    rr(ctx, -14, -5, L, 10, 4); ctx.fill();
    ctx.strokeStyle = p.metal; ctx.lineWidth = 1.4;
    rr(ctx, -14, -5, L, 10, 4); ctx.stroke();
    const core = ctx.createLinearGradient(-12, 0, L - 12, 0);
    core.addColorStop(0, 'rgba(125,255,60,0.1)');
    core.addColorStop(0.5, '#7dff3c');
    core.addColorStop(1, '#e9ffce');
    ctx.fillStyle = core;
    ctx.fillRect(-8, -1.6, L - 12, 3.2);
    // fletching
    ctx.fillStyle = p.feather;
    for (let i = 0; i < 3; i++) {
      ctx.save();
      ctx.translate(-12 - i * 1.5, 0);
      ctx.rotate(-0.5 + i * 0.45);
      ctx.beginPath();
      ctx.ellipse(-6, 0, 9, 3.2, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    // muzzle feather blade
    ctx.fillStyle = '#dfffbf';
    ctx.beginPath();
    ctx.moveTo(L - 16, -4);
    ctx.quadraticCurveTo(L + 8, 0, L - 16, 4);
    ctx.quadraticCurveTo(L - 10, 0, L - 16, -4);
    ctx.fill();
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(125,255,60,0.8)';
    ctx.beginPath(); ctx.arc(L - 14, 0, 3 + Math.sin(t * 12) * 0.8, 0, TAU); ctx.fill();
    ctx.restore();
  }
  ctx.restore();
}

/**
 * Draw a rooster-human champion.
 * opts: { portrait, bars, scale, alpha }
 */
export function drawChampion(ctx, u, t, opts = {}) {
  const p = u.def.palette;
  const role = u.def.role;
  const moving = Math.hypot(u.vx || 0, u.vy || 0) > 24;
  const speed = Math.hypot(u.vx || 0, u.vy || 0);
  const walk = u.walkPhase || 0;
  const facing = Math.cos(u.aim) >= 0 ? 1 : -1;
  let la = u.aim;
  if (facing < 0) la = Math.PI - la;
  const sc = opts.scale || 1;
  const bob = moving ? Math.sin(walk * 2) * 1.5 : Math.sin(t * 2 + (u.seed || 0)) * 0.7;
  const step = moving ? Math.sin(walk) * Math.min(1, speed / 180) : 0;

  ctx.save();
  ctx.translate(u.x, u.y);

  if (!opts.portrait) {
    shadowEllipse(ctx, 0, 2, u.r * 1.25, u.r * 0.42, 0.45);
    // team ring
    ctx.save();
    ctx.strokeStyle = TEAM[u.team].color;
    ctx.globalAlpha = 0.28;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.ellipse(0, 2, u.r * 1.15, u.r * 0.4, 0, 0, TAU); ctx.stroke();
    ctx.restore();

    if (u.isPlayer) {
      ctx.save();
      ctx.strokeStyle = '#ffd166';
      ctx.globalAlpha = 0.7;
      ctx.lineWidth = 2;
      ctx.setLineDash([7, 7]);
      ctx.lineDashOffset = -t * 26;
      ctx.beginPath(); ctx.ellipse(0, 3, u.r * 1.45, u.r * 0.52, 0, 0, TAU); ctx.stroke();
      ctx.restore();
    }
    if (u.invuln > 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = '#9beeff';
      ctx.globalAlpha = 0.4 + Math.sin(t * 14) * 0.15;
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(0, -58, 46, 0, TAU); ctx.stroke();
      ctx.restore();
    }
  }

  ctx.scale(facing * sc, sc);
  ctx.translate(0, bob);

  // ---- tail ----
  ctx.save();
  ctx.translate(-13, -52);
  const sway = Math.sin(t * 2.4 + (u.seed || 0)) * 0.08 + (moving ? Math.sin(walk * 2) * 0.05 : 0);
  for (let i = 0; i < 5; i++) {
    const a = -0.6 - i * 0.30 + sway;
    const len = 34 + (i % 3) * 8;
    ctx.save();
    ctx.rotate(a);
    ctx.fillStyle = i % 2 ? p.featherDark : p.feather;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(-len * 0.55, -7 - i * 2, -len, 0);
    ctx.quadraticCurveTo(-len * 0.5, 4, 0, 0);
    ctx.fill();
    ctx.strokeStyle = p.accent;
    ctx.globalAlpha = 0.5;
    ctx.lineWidth = 1.2;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // ---- legs ----
  drawLeg(ctx, p, -8, step, step, facing > 0);
  drawLeg(ctx, p, 8, step, -step, facing > 0);

  // ---- scarf tail ----
  ctx.save();
  ctx.strokeStyle = p.accent;
  ctx.lineWidth = 6;
  ctx.globalAlpha = 0.85;
  ctx.lineCap = 'round';
  const flap = Math.sin(t * 5 + (u.seed || 0)) * 3;
  ctx.beginPath();
  ctx.moveTo(-10, -80);
  ctx.quadraticCurveTo(-30, -74 + flap, -34, -58 + flap);
  ctx.stroke();
  ctx.restore();

  // ---- torso ----
  ctx.save();
  const skin = ctx.createLinearGradient(-30, -90, 30, -30);
  skin.addColorStop(0, p.skinLight);
  skin.addColorStop(0.35, p.skin);
  skin.addColorStop(1, p.skinDark);
  ctx.fillStyle = skin;
  ctx.beginPath();
  ctx.moveTo(-16, -30);
  ctx.bezierCurveTo(-26, -48, -31, -68, -29, -80);
  ctx.quadraticCurveTo(-22, -92, -8, -92);
  ctx.lineTo(10, -92);
  ctx.quadraticCurveTo(24, -91, 29, -80);
  ctx.bezierCurveTo(31, -66, 26, -47, 16, -30);
  ctx.quadraticCurveTo(0, -24, -16, -30);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.22)';
  ctx.lineWidth = 1;
  ctx.stroke();

  // pec + ab shading
  ctx.strokeStyle = 'rgba(90,45,25,0.45)';
  ctx.lineWidth = 1.6;
  ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0, -78); ctx.lineTo(0, -62); ctx.stroke();
  ctx.beginPath(); ctx.arc(-11, -72, 9, 0.15, Math.PI - 0.15); ctx.stroke();
  ctx.beginPath(); ctx.arc(11, -72, 9, 0.15, Math.PI - 0.15); ctx.stroke();
  for (let i = 0; i < 3; i++) {
    const y = -58 + i * 9;
    ctx.globalAlpha = 0.5;
    ctx.beginPath(); ctx.moveTo(-10, y); ctx.quadraticCurveTo(0, y + 2.5, 10, y); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, y - 3); ctx.lineTo(0, y + 5); ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // feather mantle across the shoulders
  ctx.fillStyle = p.feather;
  for (let i = -3; i <= 3; i++) {
    ctx.save();
    ctx.translate(i * 8, -84);
    ctx.rotate(i * 0.12);
    ctx.beginPath();
    ctx.moveTo(-4, 0);
    ctx.quadraticCurveTo(0, 12 + Math.abs(i) * 1.5, 4, 0);
    ctx.quadraticCurveTo(0, 3, -4, 0);
    ctx.fill();
    ctx.restore();
  }
  ctx.fillStyle = p.featherDark;
  ctx.globalAlpha = 0.7;
  ctx.beginPath(); ctx.ellipse(-20, -80, 10, 6, -0.5, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(21, -80, 9, 6, 0.5, 0, TAU); ctx.fill();
  ctx.globalAlpha = 1;

  // chest harness strap
  ctx.strokeStyle = 'rgba(20,24,26,0.9)';
  ctx.lineWidth = 6;
  ctx.beginPath(); ctx.moveTo(-19, -84); ctx.lineTo(14, -39); ctx.stroke();
  ctx.strokeStyle = p.metal;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-19, -84); ctx.lineTo(14, -39); ctx.stroke();
  ctx.fillStyle = '#ffd166';
  ctx.beginPath(); ctx.arc(2, -62, 3.6, 0, TAU); ctx.fill();
  ctx.fillStyle = '#3a2a0e';
  ctx.beginPath(); ctx.arc(2, -62, 1.6, 0, TAU); ctx.fill();
  ctx.restore();

  // ---- rear flexed arm ----
  ctx.save();
  ctx.strokeStyle = p.skinDark;
  limb(ctx, -22, -82, -34, -62, 12, p.skinDark);
  limb(ctx, -34, -62, -18, -54, 10, p.skin);
  ctx.fillStyle = p.glove;
  ctx.beginPath(); ctx.arc(-17, -52, 7, 0, TAU); ctx.fill();
  // forearm feathers
  ctx.fillStyle = p.feather;
  ctx.beginPath(); ctx.moveTo(-28, -68); ctx.lineTo(-38, -58); ctx.lineTo(-30, -56); ctx.closePath(); ctx.fill();
  ctx.restore();

  // ---- weapon arm ----
  const sh = { x: 17, y: -81 };
  const hand = { x: sh.x + Math.cos(la) * 36, y: sh.y + Math.sin(la) * 36 };
  const elbow = { x: sh.x + Math.cos(la) * 19, y: sh.y + Math.sin(la) * 19 - 3 };
  ctx.save();
  limb(ctx, sh.x, sh.y, elbow.x, elbow.y, 13, p.skin);
  ctx.save(); ctx.globalAlpha = 0.35; limb(ctx, sh.x + 2, sh.y, elbow.x + 2, elbow.y, 6, p.skinLight); ctx.restore();
  limb(ctx, elbow.x, elbow.y, hand.x, hand.y, 9, p.skin);
  // feather tufts on forearm
  ctx.fillStyle = p.feather;
  for (let i = 0; i < 2; i++) {
    ctx.save();
    ctx.translate(elbow.x, elbow.y + i * 3);
    ctx.rotate(la + Math.PI + 0.5 + i * 0.4);
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(8, -5, 13, 0); ctx.quadraticCurveTo(7, 2, 0, 0); ctx.fill();
    ctx.restore();
  }
  // glove
  ctx.fillStyle = p.glove;
  ctx.beginPath(); ctx.arc(hand.x, hand.y, 7, 0, TAU); ctx.fill();
  ctx.strokeStyle = p.accent; ctx.globalAlpha = 0.5; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.restore();

  if (role === 'sniper') {
    // support arm toward the rifle
    const s2 = { x: -6, y: -74 };
    const h2 = { x: Math.cos(la) * 22, y: -76 + Math.sin(la) * 16 };
    limb(ctx, s2.x, s2.y, h2.x, h2.y, 9, p.skin);
    ctx.fillStyle = p.glove;
    ctx.beginPath(); ctx.arc(h2.x, h2.y, 5.5, 0, TAU); ctx.fill();
  }

  drawWeapon(ctx, u, p, la, hand, t);

  // muzzle flash
  if (u.flash > 0) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = clamp(u.flash * 8, 0, 1);
    const fx = hand.x + Math.cos(la) * 34;
    const fy = hand.y + Math.sin(la) * 34;
    const fg = ctx.createRadialGradient(fx, fy, 0, fx, fy, 26);
    fg.addColorStop(0, 'rgba(255,255,230,0.9)');
    fg.addColorStop(0.4, 'rgba(150,255,90,0.6)');
    fg.addColorStop(1, 'rgba(80,255,40,0)');
    ctx.fillStyle = fg;
    ctx.beginPath(); ctx.arc(fx, fy, 26, 0, TAU); ctx.fill();
    ctx.restore();
  }

  // ---- head ----
  ctx.save();
  ctx.translate(4, -102);
  // back crest feathers
  ctx.fillStyle = p.feather;
  for (let i = 0; i < 3; i++) {
    ctx.save();
    ctx.rotate(-0.5 - i * 0.35);
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(-16, -6, -23, 0); ctx.quadraticCurveTo(-12, 4, 0, 0); ctx.fill();
    ctx.restore();
  }
  // skull
  const hg = ctx.createRadialGradient(-3, -6, 3, 0, 0, 20);
  hg.addColorStop(0, p.skinLight);
  hg.addColorStop(0.55, p.skin);
  hg.addColorStop(1, p.skinDark);
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.ellipse(0, 0, 17, 18, 0.08, 0, TAU); ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.2)'; ctx.lineWidth = 1; ctx.stroke();
  // cheek feathers
  ctx.fillStyle = p.featherDark;
  ctx.beginPath(); ctx.moveTo(-13, 2); ctx.lineTo(-24, 8); ctx.lineTo(-12, 10); ctx.closePath(); ctx.fill();
  // comb
  ctx.fillStyle = p.comb;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(-6 + i * 7, -17 - (i === 1 ? 3 : 0), 6.5 - i * 0.4, Math.PI, TAU);
    ctx.fill();
  }
  ctx.strokeStyle = p.combDark; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-12, -16); ctx.quadraticCurveTo(0, -24, 12, -16); ctx.stroke();
  // beak
  const bg2 = ctx.createLinearGradient(10, -6, 32, 2);
  bg2.addColorStop(0, '#ffdd76');
  bg2.addColorStop(1, p.beak);
  ctx.fillStyle = bg2;
  ctx.beginPath();
  ctx.moveTo(10, -5);
  ctx.quadraticCurveTo(26, -8, 32, -1);
  ctx.quadraticCurveTo(24, 3, 10, 3);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(90,40,0,0.45)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(11, -1); ctx.quadraticCurveTo(24, -1, 31, -1); ctx.stroke();
  // wattle
  ctx.fillStyle = p.comb;
  ctx.beginPath();
  ctx.ellipse(13, 9, 5, 7, 0.2, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = p.combDark; ctx.globalAlpha = 0.5; ctx.stroke(); ctx.globalAlpha = 1;
  // eye
  ctx.fillStyle = '#f7f3e6';
  ctx.beginPath(); ctx.ellipse(6, -7, 5.2, 5.6, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = '#101416';
  ctx.beginPath(); ctx.arc(7.6, -6.8, 2.6, 0, TAU); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(8.4, -7.8, 0.9, 0, TAU); ctx.fill();
  // angry brow
  ctx.strokeStyle = p.featherDark; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0, -13); ctx.lineTo(12, -10); ctx.stroke();
  ctx.restore();

  // hit flash
  if (u.hitFlash > 0 && !opts.portrait) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = clamp(u.hitFlash * 5, 0, 0.65);
    ctx.fillStyle = '#ffd9c9';
    ctx.beginPath(); ctx.ellipse(0, -62, 38, 52, 0, 0, TAU); ctx.fill();
    ctx.restore();
  }

  ctx.restore(); // scale/translate body

  // ---- above-head HUD ----
  if (!opts.portrait && opts.bars !== false) {
    const ratio = clamp(u.hp / u.maxHp, 0, 1);
    const bw = 58, bh = 7;
    const by = -150;
    ctx.save();
    // bar shadow
    ctx.fillStyle = 'rgba(0,0,0,0.65)';
    rr(ctx, -bw / 2 - 1, by - 1, bw + 2, bh + 2, 3); ctx.fill();
    ctx.fillStyle = 'rgba(25,30,31,0.9)';
    rr(ctx, -bw / 2, by, bw, bh, 2.5); ctx.fill();
    const hc = ratio > 0.55 ? '#6dff64' : ratio > 0.28 ? '#ffd166' : '#ff4d4d';
    ctx.fillStyle = hc;
    rr(ctx, -bw / 2, by, bw * ratio, bh, 2.5); ctx.fill();
    if (ratio > 0.03) {
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      rr(ctx, -bw / 2 + 1, by + 1, Math.max(0, bw * ratio - 2), 2, 1); ctx.fill();
    }
    ctx.strokeStyle = TEAM[u.team].color;
    ctx.globalAlpha = 0.65;
    ctx.lineWidth = 1;
    rr(ctx, -bw / 2, by, bw, bh, 2.5); ctx.stroke();
    // team pip
    ctx.globalAlpha = 1;
    ctx.fillStyle = TEAM[u.team].color;
    ctx.beginPath();
    ctx.moveTo(0, by - 9); ctx.lineTo(4.5, by - 14); ctx.lineTo(-4.5, by - 14);
    ctx.closePath(); ctx.fill();

    if (u.isPlayer) {
      ctx.font = '900 10px "Arial Black", system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ffd166';
      ctx.fillText('TÚ', 0, by - 19);
    }
    ctx.restore();
  }

  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* projectiles, pools, effects                                         */
/* ------------------------------------------------------------------ */
export function drawProjectile(ctx, p, t) {
  const h = 46 + (p.z || 0);
  if (p.kind === 'egg') {
    // ground shadow
    shadowEllipse(ctx, p.x, p.y, 7 + (p.z || 0) * 0.02, 3.2, 0.35);
    ctx.save();
    ctx.translate(p.x, p.y - h);
    ctx.rotate(p.spin || 0);
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(0, 0, 2, 0, 0, 26);
    glow.addColorStop(0, 'rgba(125,255,60,0.32)');
    glow.addColorStop(1, 'rgba(125,255,60,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(0, 0, 26, 0, TAU); ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    drawEgg(ctx, 0, 0, 9, p.seed, false);
    ctx.restore();
  } else {
    shadowEllipse(ctx, p.x, p.y, 8, 3, 0.3);
    ctx.save();
    ctx.translate(p.x, p.y - h);
    ctx.rotate(p.angle);
    // trail
    ctx.globalCompositeOperation = 'lighter';
    const tr = ctx.createLinearGradient(-52, 0, 6, 0);
    tr.addColorStop(0, 'rgba(125,255,60,0)');
    tr.addColorStop(0.6, 'rgba(125,255,60,0.32)');
    tr.addColorStop(1, 'rgba(240,255,210,0.9)');
    ctx.strokeStyle = tr;
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-54, 0); ctx.lineTo(0, 0); ctx.stroke();
    // feather body
    const fb = ctx.createLinearGradient(-8, 0, 30, 0);
    fb.addColorStop(0, '#2f6b32');
    fb.addColorStop(0.5, '#9dff6e');
    fb.addColorStop(1, '#f4ffe4');
    ctx.fillStyle = fb;
    ctx.beginPath();
    ctx.moveTo(-14, 0);
    ctx.quadraticCurveTo(2, -7, 28, 0);
    ctx.quadraticCurveTo(2, 7, -14, 0);
    ctx.fill();
    ctx.strokeStyle = 'rgba(220,255,200,0.9)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-16, 0); ctx.lineTo(26, 0); ctx.stroke();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(180,255,130,0.8)';
    ctx.beginPath(); ctx.arc(22, 0, 3.2, 0, TAU); ctx.fill();
    ctx.restore();
  }
}

export function drawPool(ctx, pool, t) {
  const lifeRatio = pool.life / pool.maxLife;
  const fade = clamp(lifeRatio * 4, 0, 1) * clamp(pool.life * 2, 0, 1);
  const r = pool.r * (0.9 + Math.sin(t * 3 + pool.seed) * 0.03) * (0.4 + 0.6 * clamp(pool.maxLife - pool.life + 0.25, 0, 1));
  if (r < 2) return;
  ctx.save();
  ctx.globalAlpha = fade;
  // dark scorched ring
  ctx.fillStyle = 'rgba(4,8,4,0.65)';
  ctx.beginPath(); ctx.ellipse(pool.x, pool.y + 4, r * 1.16, r * 0.62, 0, 0, TAU); ctx.fill();
  // lava body
  const g = ctx.createRadialGradient(pool.x, pool.y, r * 0.1, pool.x, pool.y, r);
  g.addColorStop(0, 'rgba(215,255,180,0.95)');
  g.addColorStop(0.3, 'rgba(125,255,60,0.9)');
  g.addColorStop(0.75, 'rgba(42,170,40,0.75)');
  g.addColorStop(1, 'rgba(10,60,10,0.15)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.ellipse(pool.x, pool.y, r, r * 0.55, 0, 0, TAU); ctx.fill();
  // bubbles
  ctx.fillStyle = 'rgba(235,255,210,0.8)';
  for (let i = 0; i < 5; i++) {
    const a = pool.seed + i * 2.4;
    const bx = pool.x + Math.cos(a + t * 0.5 + i) * r * 0.62;
    const by = pool.y + Math.sin(a * 1.7 + t * 0.6) * r * 0.3;
    const s = 1.4 + Math.abs(Math.sin(t * 4 + i + pool.seed)) * 2.2;
    ctx.beginPath(); ctx.arc(bx, by, s, 0, TAU); ctx.fill();
  }
  ctx.globalCompositeOperation = 'lighter';
  const glow = ctx.createRadialGradient(pool.x, pool.y, 0, pool.x, pool.y, r * 1.4);
  glow.addColorStop(0, 'rgba(125,255,60,0.20)');
  glow.addColorStop(1, 'rgba(125,255,60,0)');
  ctx.fillStyle = glow;
  ctx.beginPath(); ctx.ellipse(pool.x, pool.y, r * 1.4, r * 0.8, 0, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawParticle(ctx, p) {
  const a = clamp(p.life / p.maxLife, 0, 1);
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot || 0);
  ctx.globalAlpha = a;
  if (p.kind === 'feather') {
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.ellipse(0, 0, p.size * 1.8, p.size * 0.7, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
    ctx.lineWidth = 0.7;
    ctx.beginPath(); ctx.moveTo(-p.size * 1.6, 0); ctx.lineTo(p.size * 1.6, 0); ctx.stroke();
  } else if (p.kind === 'goo') {
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = p.color;
    ctx.beginPath(); ctx.arc(0, 0, p.size * a + 0.5, 0, TAU); ctx.fill();
  } else if (p.kind === 'smoke') {
    ctx.fillStyle = p.color;
    ctx.globalAlpha = a * 0.4;
    ctx.beginPath(); ctx.arc(0, 0, p.size * (1.6 - a * 0.6), 0, TAU); ctx.fill();
  } else if (p.kind === 'ember') {
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = p.color;
    ctx.beginPath(); ctx.arc(0, 0, p.size, 0, TAU); ctx.fill();
  } else {
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = p.color;
    ctx.beginPath(); ctx.arc(0, 0, Math.max(0.4, p.size * a), 0, TAU); ctx.fill();
  }
  ctx.restore();
}

export function drawFloatText(ctx, f) {
  const a = clamp(f.life / f.maxLife, 0, 1);
  ctx.save();
  ctx.globalAlpha = a;
  ctx.font = `900 ${f.size}px "Arial Black", system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'rgba(0,0,0,0.8)';
  ctx.strokeText(f.text, f.x, f.y);
  ctx.fillStyle = f.color;
  ctx.fillText(f.text, f.x, f.y);
  ctx.restore();
}

export function drawBeam(ctx, b) {
  const a = clamp(b.life / b.maxLife, 0, 1);
  const w = b.width * (0.5 + a * 0.8);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = a;
  ctx.lineCap = 'round';
  const g = ctx.createLinearGradient(b.x1, b.y1, b.x2, b.y2);
  g.addColorStop(0, 'rgba(255,255,230,0.95)');
  g.addColorStop(0.6, 'rgba(150,255,90,0.9)');
  g.addColorStop(1, 'rgba(80,255,60,0.2)');
  ctx.strokeStyle = g;
  ctx.lineWidth = w;
  ctx.shadowColor = '#7dff3c';
  ctx.shadowBlur = 30;
  ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,240,0.9)';
  ctx.lineWidth = Math.max(1, w * 0.22);
  ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
  ctx.restore();
  // flare
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = a;
  const fg = ctx.createRadialGradient(b.x1, b.y1, 0, b.x1, b.y1, 46);
  fg.addColorStop(0, 'rgba(255,255,220,0.9)');
  fg.addColorStop(1, 'rgba(125,255,60,0)');
  ctx.fillStyle = fg;
  ctx.beginPath(); ctx.arc(b.x1, b.y1, 46, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawShockwave(ctx, s) {
  const a = clamp(s.life / s.maxLife, 0, 1);
  const r = s.r;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = a * 0.8;
  ctx.strokeStyle = s.color;
  ctx.lineWidth = 4 * a + 1;
  ctx.beginPath(); ctx.ellipse(s.x, s.y, r, r * 0.55, 0, 0, TAU); ctx.stroke();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */
function roleIcon(ctx, x, y, role, size, color) {
  ctx.save();
  ctx.translate(x, y);
  if (role === 'brawler') {
    ctx.fillStyle = '#060806';
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.ellipse(0, 0, size * 0.5, size * 0.65, -0.2, 0, TAU); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = '#7dff3c';
    ctx.beginPath(); ctx.moveTo(-size * 0.2, -size * 0.2); ctx.lineTo(0, 0); ctx.lineTo(-size * 0.1, size * 0.3); ctx.stroke();
  } else {
    ctx.rotate(-0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.ellipse(0, 0, size * 0.66, size * 0.26, 0, 0, TAU); ctx.fill();
    ctx.strokeStyle = '#eaffd2';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(-size * 0.6, 0); ctx.lineTo(size * 0.6, 0); ctx.stroke();
  }
  ctx.restore();
}

function panel(ctx, x, y, w, h, r = 10) {
  ctx.fillStyle = 'rgba(6,9,10,0.78)';
  rr(ctx, x, y, w, h, r); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.10)';
  ctx.lineWidth = 1;
  rr(ctx, x, y, w, h, r); ctx.stroke();
}

export function drawHUD(ctx, game, view) {
  const { w, h, insets, isTouch, layout } = view;
  const top = insets.top + 10;
  const player = game.player;

  // ---- scoreboard ----
  const mobile = isTouch;
  const sw = mobile ? 196 : 300;
  const sh = mobile ? 44 : 56;
  const sx = w / 2 - sw / 2;
  panel(ctx, sx, top, sw, sh, 12);
  // team color strips
  const strip = 5;
  ctx.fillStyle = TEAM[0].color;
  rr(ctx, sx + 1, top + 1, strip, sh - 2, 4); ctx.fill();
  ctx.fillStyle = TEAM[1].color;
  rr(ctx, sx + sw - strip - 1, top + 1, strip, sh - 2, 4); ctx.fill();

  const scoreY = top + (mobile ? 21 : 25);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `900 ${mobile ? 19 : 24}px "Arial Black", system-ui, sans-serif`;
  ctx.fillStyle = TEAM[0].soft;
  ctx.fillText(String(game.scores[0]).padStart(2, '0'), sx + 46, scoreY);
  ctx.fillStyle = TEAM[1].soft;
  ctx.fillText(String(game.scores[1]).padStart(2, '0'), sx + sw - 46, scoreY);

  const tsec = Math.max(0, Math.ceil(game.timer));
  const mm = Math.floor(tsec / 60);
  const ss = String(tsec % 60).padStart(2, '0');
  ctx.font = `900 ${mobile ? 14 : 17}px "Arial Black", system-ui, sans-serif`;
  ctx.fillStyle = tsec <= 15 ? '#ff6a5c' : '#f2e8d5';
  ctx.fillText(`${mm}:${ss}`, w / 2, scoreY - (mobile ? 0 : 1));
  ctx.font = `800 ${mobile ? 6 : 7}px system-ui, sans-serif`;
  ctx.fillStyle = 'rgba(220,210,190,0.55)';
  ctx.fillText('PRIMERO A 10', w / 2, top + sh - (mobile ? 7 : 9));
  ctx.font = `800 ${mobile ? 7 : 8}px system-ui, sans-serif`;
  ctx.fillStyle = 'rgba(56,214,255,0.75)';
  ctx.fillText('AZUL', sx + 46, top + sh - (mobile ? 7 : 9));
  ctx.fillStyle = 'rgba(255,77,99,0.8)';
  ctx.fillText('ROJO', sx + sw - 46, top + sh - (mobile ? 7 : 9));

  // ---- rosters ----
  const rosterY = top + sh + (mobile ? 8 : 9);
  if (!mobile) {
    drawRoster(ctx, game, 0, 14, rosterY, 186, player);
    drawRoster(ctx, game, 1, w - 14 - 186, rosterY, 186, player);
  } else {
    drawRosterCompact(ctx, game, 0, 8 + insets.left, rosterY, player);
    drawRosterCompact(ctx, game, 1, w - 8 - insets.right, rosterY, player);
  }

  // ---- kill feed ----
  const feedX = mobile ? w - 8 - insets.right : w - 14 - 186;
  let feedY = rosterY + (mobile ? 44 : 82);
  ctx.textAlign = 'right';
  for (let i = 0; i < Math.min(3, game.feed.length); i++) {
    const f = game.feed[i];
    const a = clamp(f.life / 1.2, 0, 1);
    ctx.globalAlpha = a;
    ctx.font = `800 ${mobile ? 8 : 9.5}px system-ui, sans-serif`;
    const ty = feedY + i * (mobile ? 11 : 13);
    ctx.fillStyle = 'rgba(5,8,8,0.55)';
    ctx.fillRect(feedX - 150, ty - 8, 150, 11);
    ctx.fillStyle = TEAM[f.team].soft;
    ctx.fillText(f.a, feedX - 34, ty);
    ctx.fillStyle = 'rgba(240,230,210,0.55)';
    ctx.textAlign = 'center';
    ctx.fillText('▶', feedX - 24, ty);
    ctx.textAlign = 'right';
    ctx.fillStyle = TEAM[1 - f.team].soft;
    ctx.fillText(f.b, feedX - 2, ty);
  }
  ctx.globalAlpha = 1;

  // ---- announcements ----
  if (game.announce && game.announce.life > 0) {
    const an = game.announce;
    const k = 1 - an.life / an.maxLife;
    const pop = clamp(k * 7, 0, 1);
    const fade = clamp(an.life / 0.5, 0, 1);
    ctx.save();
    ctx.globalAlpha = fade;
    ctx.translate(w / 2, h * 0.23);
    ctx.scale(0.85 + pop * 0.15, 0.85 + pop * 0.15);
    ctx.textAlign = 'center';
    ctx.font = `900 ${mobile ? 26 : 42}px "Arial Black", system-ui, sans-serif`;
    ctx.lineWidth = 6;
    ctx.strokeStyle = 'rgba(4,7,6,0.8)';
    ctx.strokeText(an.text, 0, 0);
    const g = ctx.createLinearGradient(0, -28, 0, 16);
    g.addColorStop(0, '#fff6da');
    g.addColorStop(0.55, an.color);
    g.addColorStop(1, '#8c3a12');
    ctx.fillStyle = g;
    ctx.fillText(an.text, 0, 0);
    if (an.sub) {
      ctx.font = `800 ${mobile ? 9 : 11}px system-ui, sans-serif`;
      ctx.fillStyle = 'rgba(240,232,215,0.82)';
      ctx.fillText(an.sub, 0, mobile ? 18 : 24);
    }
    ctx.restore();
  }

  // ---- player status / abilities ----
  if (player) {
    if (player.alive) {
      if (mobile) drawAbilityButton(ctx, layout.special, player.specialCd, ROLE[player.def.role].specialCd, 'ESP', player.def.role, '#ffd166');
      if (mobile) drawAbilityButton(ctx, layout.dash, player.dashCd, ROLE[player.def.role].dashCd, 'DASH', 'dash', TEAM[0].color);
      if (!mobile) drawDesktopAbilities(ctx, w, h, insets, player);
    } else {
      ctx.save();
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(255,80,80,0.9)';
      ctx.font = `900 ${mobile ? 16 : 22}px "Arial Black", system-ui, sans-serif`;
      ctx.fillText('ELIMINADO', w / 2, h * 0.42);
      ctx.fillStyle = 'rgba(240,230,210,0.8)';
      ctx.font = `800 ${mobile ? 10 : 12}px system-ui, sans-serif`;
      ctx.fillText(`VUELVES EN ${Math.max(0, player.respawn).toFixed(1)}s`, w / 2, h * 0.42 + (mobile ? 17 : 22));
      ctx.restore();
    }
  }

  // ---- touch sticks ----
  if (isTouch && game.state === 'playing') {
    drawStick(ctx, layout.move, view.moveStick, 'MOVER', TEAM[0].color);
    drawStick(ctx, layout.aim, view.aimStick, 'APUNTAR', '#ffd166');
  }

  // ---- hint ----
  if (!mobile && game.state === 'playing' && game.roundTime < 9) {
    const a = clamp(9 - game.roundTime, 0, 1) * clamp(game.roundTime, 0, 1);
    ctx.save();
    ctx.globalAlpha = Math.min(1, a) * 0.75;
    ctx.textAlign = 'center';
    ctx.font = '800 10px system-ui, sans-serif';
    ctx.fillStyle = '#e5dbc8';
    ctx.fillText('WASD MOVER · RATÓN APUNTAR · CLICK LANZAR · SHIFT DASH · ESPACIO ESPECIAL', w / 2, h - 18 - insets.bottom);
    ctx.restore();
  }
}

function drawRoster(ctx, game, team, x, y, width, player) {
  panel(ctx, x - 6, y - 5, width + 12, 78, 9);
  const units = game.units.filter(u => u.team === team);
  for (let i = 0; i < units.length; i++) {
    const u = units[i];
    const ry = y + 5 + i * 17;
    roleIcon(ctx, x + 6, ry + 2, u.def.role, 8, TEAM[team].color);
    ctx.textAlign = 'left';
    ctx.font = `900 8.5px system-ui, sans-serif`;
    ctx.fillStyle = u.alive ? '#ede3d0' : 'rgba(160,150,135,0.45)';
    ctx.fillText(u.def.name, x + 16, ry + 4);
    if (u.isPlayer) {
      ctx.fillStyle = '#ffd166';
      ctx.fillText('●', x + 16 + ctx.measureText(u.def.name).width + 3, ry + 4);
    }
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    rr(ctx, x + 56, ry - 1, width - 78, 4, 2); ctx.fill();
    if (u.alive) {
      const ratio = clamp(u.hp / u.maxHp, 0, 1);
      ctx.fillStyle = ratio > 0.5 ? TEAM[team].color : ratio > 0.25 ? '#ffd166' : '#ff4d4d';
      rr(ctx, x + 56, ry - 1, (width - 78) * ratio, 4, 2); ctx.fill();
    } else {
      ctx.fillStyle = 'rgba(255,90,90,0.3)';
      ctx.font = '800 7px system-ui, sans-serif';
      ctx.fillText(`${Math.max(0, u.respawn).toFixed(0)}s`, x + width - 42, ry + 4);
    }
  }
}

function drawRosterCompact(ctx, game, team, x, y, player) {
  const units = game.units.filter(u => u.team === team);
  const right = team === 1;
  for (let i = 0; i < units.length; i++) {
    const u = units[i];
    const ry = y + 3 + i * 9;
    const bx = right ? x - 58 : x + 14;
    roleIcon(ctx, right ? x - 61 : x + 5, ry + 3, u.def.role, 5.5, TEAM[team].color);
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    rr(ctx, bx, ry, 58, 5, 2); ctx.fill();
    if (u.alive) {
      const ratio = clamp(u.hp / u.maxHp, 0, 1);
      ctx.fillStyle = u.isPlayer ? '#ffd166' : ratio > 0.5 ? TEAM[team].color : ratio > 0.25 ? '#ffd166' : '#ff4d4d';
      rr(ctx, bx, ry, 58 * ratio, 5, 2); ctx.fill();
    } else {
      ctx.fillStyle = 'rgba(255,90,90,0.35)';
      rr(ctx, bx, ry, 58, 5, 2); ctx.fill();
    }
  }
}

function drawDesktopAbilities(ctx, w, h, insets, player) {
  const role = ROLE[player.def.role];
  const baseY = h - 34 - insets.bottom;
  const items = [
    { label: 'DASH', key: 'SHIFT', cd: player.dashCd, max: role.dashCd, color: TEAM[0].color, icon: 'dash' },
    { label: 'ESPECIAL', key: 'ESPACIO', cd: player.specialCd, max: role.specialCd, color: '#ffd166', icon: player.def.role }
  ];
  const totalW = 300;
  let x = w / 2 - totalW / 2;
  for (const it of items) {
    const ready = it.cd <= 0;
    panel(ctx, x, baseY - 24, 142, 30, 8);
    roleIcon(ctx, x + 17, baseY - 9, it.icon === 'dash' ? 'sniper' : it.icon, 10, it.color);
    ctx.textAlign = 'left';
    ctx.font = '900 9px system-ui, sans-serif';
    ctx.fillStyle = ready ? it.color : 'rgba(180,170,155,0.5)';
    ctx.fillText(it.label, x + 30, baseY - 5);
    ctx.font = '800 7px system-ui, sans-serif';
    ctx.fillStyle = 'rgba(220,210,190,0.5)';
    ctx.fillText(ready ? it.key : `${it.cd.toFixed(1)}s`, x + 30, baseY + 3);
    // cooldown bar
    const ratio = ready ? 1 : 1 - it.cd / it.max;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    rr(ctx, x + 92, baseY - 10, 42, 4, 2); ctx.fill();
    ctx.fillStyle = it.color;
    rr(ctx, x + 92, baseY - 10, 42 * ratio, 4, 2); ctx.fill();
    x += 156;
  }
}

function drawAbilityButton(ctx, b, cd, max, label, icon, color) {
  const ready = cd <= 0;
  ctx.save();
  ctx.translate(b.x, b.y);
  ctx.fillStyle = 'rgba(6,10,10,0.62)';
  ctx.beginPath(); ctx.arc(0, 0, b.r, 0, TAU); ctx.fill();
  ctx.strokeStyle = ready ? color : 'rgba(255,255,255,0.18)';
  ctx.globalAlpha = ready ? 0.9 : 0.55;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(0, 0, b.r, 0, TAU); ctx.stroke();
  ctx.globalAlpha = 1;
  if (!ready) {
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.75;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, b.r - 1.5, -Math.PI / 2, -Math.PI / 2 + TAU * (1 - cd / max));
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
  roleIcon(ctx, 0, -3, icon === 'dash' ? 'sniper' : icon, b.r * 0.6, ready ? color : 'rgba(180,170,155,0.6)');
  ctx.textAlign = 'center';
  ctx.font = '900 6.5px system-ui, sans-serif';
  ctx.fillStyle = ready ? 'rgba(240,232,215,0.9)' : 'rgba(180,170,155,0.6)';
  ctx.fillText(label, 0, b.r * 0.62);
  ctx.restore();
}

function drawStick(ctx, base, state, label, color) {
  if (!base) return;
  const active = !!state;
  ctx.save();
  ctx.globalAlpha = active ? 0.72 : 0.34;
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(base.x, base.y, base.r, 0, TAU); ctx.stroke();
  ctx.fillStyle = 'rgba(5,9,9,0.25)';
  ctx.beginPath(); ctx.arc(base.x, base.y, base.r, 0, TAU); ctx.fill();
  if (active) {
    const dx = (state.x || 0) * base.r * 0.55;
    const dy = (state.y || 0) * base.r * 0.55;
    ctx.globalAlpha = 0.85;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(base.x + dx, base.y + dy, base.r * 0.34, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.25;
    ctx.beginPath(); ctx.arc(base.x + dx, base.y + dy, base.r * 0.52, 0, TAU); ctx.fill();
  } else {
    ctx.globalAlpha = 0.5;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(base.x, base.y, base.r * 0.28, 0, TAU); ctx.fill();
  }
  ctx.globalAlpha = 0.6;
  ctx.textAlign = 'center';
  ctx.font = '900 7px system-ui, sans-serif';
  ctx.fillStyle = '#e9dfca';
  ctx.fillText(label, base.x, base.y + base.r + 13);
  ctx.restore();
}

export function drawOffscreenMarkers(ctx, game, view) {
  const { w, h, camera, insets } = view;
  for (const u of game.units) {
    if (!u.alive || u.team === 0) continue;
    const s = worldToScreen(u.x, u.y - 60, camera, w, h);
    const margin = 26;
    if (s.x > margin && s.x < w - margin && s.y > margin + insets.top && s.y < h - margin) continue;
    const cx = w / 2, cy = h / 2;
    const ang = Math.atan2(s.y - cy, s.x - cx);
    const rx = Math.min(w / 2 - margin, h / 2 - margin);
    const ex = cx + Math.cos(ang) * (w / 2 - margin);
    const ey = cy + Math.sin(ang) * (h / 2 - margin);
    ctx.save();
    ctx.translate(ex, ey);
    ctx.rotate(ang);
    ctx.globalAlpha = 0.7;
    ctx.fillStyle = TEAM[1].color;
    ctx.beginPath(); ctx.moveTo(7, 0); ctx.lineTo(-5, -5); ctx.lineTo(-5, 5); ctx.closePath(); ctx.fill();
    ctx.restore();
  }
}

export function worldToScreen(x, y, camera, w, h) {
  return {
    x: (x - camera.x) * camera.zoom + w / 2 + camera.shakeX,
    y: (y - camera.y) * camera.zoom + h / 2 + camera.shakeY
  };
}

export function drawVignette(ctx, w, h) {
  const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.32, w / 2, h / 2, Math.max(w, h) * 0.78);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.65, 'rgba(0,0,0,0.16)');
  g.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}

export function drawPause(ctx, w, h) {
  ctx.save();
  ctx.fillStyle = 'rgba(3,5,6,0.7)';
  ctx.fillRect(0, 0, w, h);
  ctx.textAlign = 'center';
  ctx.fillStyle = '#f2e8d5';
  ctx.font = '900 42px "Arial Black", system-ui, sans-serif';
  ctx.fillText('PAUSA', w / 2, h / 2);
  ctx.font = '800 11px system-ui, sans-serif';
  ctx.fillStyle = 'rgba(220,210,190,0.7)';
  ctx.fillText('P O ESC PARA CONTINUAR', w / 2, h / 2 + 26);
  ctx.restore();
}

export { rr };

import { FIGHTERS, ROLE, WORLD, TEAM, SPAWNS, TAU } from './roster.js';
import { Sfx } from './audio.js';
import {
  drawArena, drawChampion, drawProjectile, drawPool, drawParticle,
  drawFloatText, drawBeam, drawShockwave, clamp
} from './render.js';

const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
const dist2 = (ax, ay, bx, by) => { const dx = ax - bx, dy = ay - by; return dx * dx + dy * dy; };

function angLerp(from, to, t) {
  let d = ((to - from + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return from + d * t;
}

export class Game {
  constructor() {
    this.state = 'attract';
    this.selected = 0;
    this.onEnd = null;
    this.t = 0;
    this.shake = 0;
    this.units = [];
    this.projectiles = [];
    this.pools = [];
    this.particles = [];
    this.floats = [];
    this.beams = [];
    this.shocks = [];
    this.feed = [];
    this.announce = null;
    this.scores = [0, 0];
    this.timer = 120;
    this.roundTime = 0;
    this.player = null;
    this.firstBlood = false;
    this.result = null;
    this.reset(true);
  }

  reset(attract) {
    this.units = [];
    this.projectiles = [];
    this.pools = [];
    this.particles = [];
    this.floats = [];
    this.beams = [];
    this.shocks = [];
    this.feed = [];
    this.announce = null;
    this.scores = [0, 0];
    this.timer = 120;
    this.roundTime = 0;
    this.firstBlood = false;
    this.result = null;
    this.shake = 0;
    this.player = null;

    const defs = FIGHTERS;
    for (let i = 0; i < defs.length; i++) {
      const def = defs[i];
      const spawn = SPAWNS[i];
      const role = ROLE[def.role];
      const u = {
        def, team: def.team, role: def.role,
        x: spawn[0], y: spawn[1], spawnX: spawn[0], spawnY: spawn[1],
        vx: 0, vy: 0, kx: 0, ky: 0,
        r: role.radius, speed: role.speed,
        hp: role.hp, maxHp: role.hp,
        aim: def.team === 0 ? 0 : Math.PI,
        cooldown: rand(0.2, 0.9), dashCd: 0, dashT: 0, dashDirX: 0, dashDirY: 0,
        specialCd: rand(3, 6),
        alive: true, respawn: 0, invuln: 1.2,
        hitFlash: 0, burnT: 0, burnDps: 0, burnFrom: null,
        walkPhase: rand(0, TAU), seed: rand(0, 100),
        flash: 0,
        isPlayer: false,
        target: null, retarget: 0, strafeDir: Math.random() < 0.5 ? -1 : 1,
        streak: 0, slowT: 0, poolAcc: 0,
        lastX: spawn[0], lastY: spawn[1]
      };
      this.units.push(u);
    }
    if (!attract) {
      this.player = this.units.find(u => u.team === 0 && u.def.id === FIGHTERS[this.selected].id) || this.units[0];
      this.player.isPlayer = true;
    }
    // spawn shimmer
    for (const u of this.units) {
      this.spawnShock(u.x, u.y, 70, TEAM[u.team].color, 0.5);
    }
  }

  start(index = this.selected) {
    this.selected = index;
    this.reset(false);
    this.state = 'playing';
    this.announce = { text: '¡A LA CARGA!', sub: 'PRIMERO A 10 BAJAS · 2:00', life: 2.1, maxLife: 2.1, color: '#ffd166' };
    Sfx.ensure();
    Sfx.ui();
    Sfx.respawn();
  }

  startAttract() {
    this.state = 'attract';
    this.reset(true);
  }

  shakeBy(v) { this.shake = Math.min(22, this.shake + v); }

  spawnParticle(o) {
    if (this.particles.length > 760) this.particles.splice(0, 60);
    this.particles.push(o);
  }

  burst(x, y, n, opts = {}) {
    const {
      colors = ['#7dff3c', '#b6ff7a', '#2f6b32'],
      speed = [40, 190], size = [1.5, 4], life = [0.3, 0.7],
      kind = 'goo', gravity = 160, spread = TAU, dir = 0, rot = true
    } = opts;
    for (let i = 0; i < n; i++) {
      const a = dir + rand(-spread / 2, spread / 2);
      const sp = rand(speed[0], speed[1]);
      this.spawnParticle({
        x, y: y - rand(34, 60), vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - rand(10, 60),
        life: rand(life[0], life[1]), maxLife: 0.8,
        size: rand(size[0], size[1]), color: colors[Math.floor(Math.random() * colors.length)],
        kind, gravity, rot: rot ? rand(0, TAU) : 0, vr: rand(-7, 7), drag: 0.9
      });
    }
  }

  spawnFloat(x, y, text, color = '#fff', size = 15) {
    this.floats.push({ x: x + rand(-8, 8), y, text, color, size, life: 0.85, maxLife: 0.85 });
  }

  spawnShock(x, y, maxR, color, life = 0.5) {
    this.shocks.push({ x, y, r: maxR * 0.15, maxR, life, maxLife: life, color });
  }

  /* ------------------------------------------------------------------ */
  update(dt, input) {
    dt = Math.min(dt, 0.04);
    this.t += dt;
    this.shake *= Math.pow(0.0025, dt);
    this.updateEffects(dt);
    if (this.state === 'over') return;
    if (this.state === 'paused') return;
    if (this.state === 'attract') {
      this.timer -= dt;
      if (this.timer <= 0 || this.scores[0] >= 10 || this.scores[1] >= 10) { this.reset(true); return; }
    } else {
      this.roundTime += dt;
      this.timer -= dt;
      if (this.timer <= 0) { this.timer = 0; this.endRound(); return; }
    }

    for (const u of this.units) {
      if (!u.alive) {
        u.respawn -= dt;
        if (u.respawn <= 0) this.respawn(u);
        continue;
      }
      u.cooldown = Math.max(0, u.cooldown - dt);
      u.dashCd = Math.max(0, u.dashCd - dt);
      u.specialCd = Math.max(0, u.specialCd - dt);
      u.invuln = Math.max(0, u.invuln - dt);
      u.hitFlash = Math.max(0, u.hitFlash - dt);
      u.flash = Math.max(0, u.flash - dt);
      u.slowT = Math.max(0, u.slowT - dt);

      if (u.burnT > 0) {
        u.burnT -= dt;
        this.damage(u, u.burnDps * dt, u.burnFrom, { silent: true, burn: true });
        if (Math.random() < dt * 14) {
          this.spawnParticle({
            x: u.x + rand(-16, 16), y: u.y - rand(30, 100), vx: rand(-15, 15), vy: -rand(20, 60),
            life: rand(0.2, 0.5), maxLife: 0.5, size: rand(1.5, 3), color: Math.random() < 0.5 ? '#ffb347' : '#7dff3c',
            kind: 'ember', gravity: -30, rot: 0, vr: 0, drag: 0.95
          });
        }
        if (!u.alive) continue;
      }

      if (this.state === 'playing' && u.isPlayer) this.updatePlayer(u, dt, input);
      else this.updateAI(u, dt);

      // integrate
      if (u.dashT > 0) {
        u.dashT -= dt;
        const sp = 720;
        u.vx = u.dashDirX * sp;
        u.vy = u.dashDirY * sp;
        if (Math.random() < 0.6) this.spawnParticle({
          x: u.x, y: u.y - 30, vx: rand(-20, 20), vy: rand(-10, 30), life: 0.34, maxLife: 0.34,
          size: rand(6, 12), color: TEAM[u.team].color, kind: 'smoke', gravity: 0, rot: 0, vr: 0, drag: 0.9
        });
      }
      u.x += (u.vx + u.kx) * dt;
      u.y += (u.vy + u.ky) * dt;
      u.kx *= Math.pow(0.0009, dt);
      u.ky *= Math.pow(0.0009, dt);

      const minX = WORLD.left + u.r * 0.4, maxX = WORLD.right - u.r * 0.4;
      const minY = WORLD.top + u.r * 0.4, maxY = WORLD.bottom - u.r * 0.4;
      if (u.x < minX) { u.x = minX; u.vx = Math.abs(u.vx) * 0.2; u.kx = Math.abs(u.kx) * 0.2; }
      if (u.x > maxX) { u.x = maxX; u.vx = -Math.abs(u.vx) * 0.2; u.kx = -Math.abs(u.kx) * 0.2; }
      if (u.y < minY) { u.y = minY; u.vy = Math.abs(u.vy) * 0.2; u.ky = Math.abs(u.ky) * 0.2; }
      if (u.y > maxY) { u.y = maxY; u.vy = -Math.abs(u.vy) * 0.2; u.ky = -Math.abs(u.ky) * 0.2; }

      const spd = Math.hypot(u.vx, u.vy);
      if (spd > 25) u.walkPhase += dt * (4 + spd * 0.035);
      else u.walkPhase += dt * 1.2;
      u.lastX = u.x; u.lastY = u.y;
    }

    this.updateProjectiles(dt);
    this.updatePools(dt);
  }

  updateEffects(dt) {
    this.feed = this.feed.filter(f => (f.life -= dt) > 0);
    if (this.announce) {
      this.announce.life -= dt;
      if (this.announce.life <= 0) this.announce = null;
    }
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) { this.particles.splice(i, 1); continue; }
      p.vy += (p.gravity || 0) * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= Math.pow(p.drag ?? 0.95, dt * 60);
      p.rot += (p.vr || 0) * dt;
      if (p.kind === 'feather' || p.kind === 'smoke') p.vy *= Math.pow(0.55, dt * 8);
    }
    for (let i = this.floats.length - 1; i >= 0; i--) {
      const f = this.floats[i];
      f.life -= dt;
      f.y -= dt * 34;
      if (f.life <= 0) this.floats.splice(i, 1);
    }
    for (let i = this.beams.length - 1; i >= 0; i--) {
      this.beams[i].life -= dt;
      if (this.beams[i].life <= 0) this.beams.splice(i, 1);
    }
    for (let i = this.shocks.length - 1; i >= 0; i--) {
      const s = this.shocks[i];
      s.life -= dt;
      s.r += (s.maxR - s.r) * Math.min(1, dt * 10);
      if (s.life <= 0) this.shocks.splice(i, 1);
    }
  }

  /* ------------------------------------------------------------------ */
  updatePlayer(u, dt, input) {
    if (!u.alive) return;
    let mx = input.moveX || 0, my = input.moveY || 0;
    const ml = Math.hypot(mx, my);
    if (ml > 1) { mx /= ml; my /= ml; }

    if (input.dash && u.dashCd <= 0) this.doDash(u, mx, my);
    if (input.special && u.specialCd <= 0) this.doSpecial(u);

    // Aim
    let aimAngle = null;
    if (input.hasAim) {
      aimAngle = Math.atan2(input.aimY - u.y, input.aimX - u.x);
    } else {
      const target = this.nearestEnemy(u, 1200);
      if (target) {
        const role = ROLE[u.role];
        const tt = Math.hypot(target.x - u.x, target.y - u.y) / role.projSpeed;
        aimAngle = Math.atan2(target.y + target.vy * tt * 0.7 - u.y, target.x + target.vx * tt * 0.7 - u.x);
      }
    }
    if (aimAngle !== null) u.aim = aimAngle;

    if (u.dashT <= 0) {
      const slow = u.slowT > 0 ? 0.72 : 1;
      const k = Math.min(1, dt * 13);
      u.vx += (mx * u.speed * slow - u.vx) * k;
      u.vy += (my * u.speed * slow - u.vy) * k;
      if (ml < 0.05) {
        u.vx *= Math.pow(0.001, dt);
        u.vy *= Math.pow(0.001, dt);
      }
    }

    if (input.firing && u.cooldown <= 0) {
      this.firePrimary(u, u.aim);
    }
  }

  updateAI(u, dt) {
    u.retarget -= dt;
    let target = u.target;
    if (!target || !target.alive || u.retarget <= 0) {
      target = this.nearestEnemy(u, 2400);
      u.target = target;
      u.retarget = rand(1.1, 2.2);
      if (Math.random() < 0.45) u.strafeDir *= -1;
    }
    if (!target) return;

    const role = ROLE[u.role];
    const dx = target.x - u.x, dy = target.y - u.y;
    const dist = Math.hypot(dx, dy) || 1;
    const nx = dx / dist, ny = dy / dist;
    const pref = role.preferred;
    let mx = 0, my = 0;

    if (dist > pref + 65) { mx += nx; my += ny; }
    else if (dist < pref - 90) { mx -= nx; my -= ny; }
    else {
      mx += -ny * u.strafeDir;
      my += nx * u.strafeDir;
      if (Math.random() < dt * 0.5) u.strafeDir *= -1;
    }

    // keep distance if sniper and enemy too close
    if (u.role === 'sniper' && dist < 240) { mx -= nx * 1.3; my -= ny * 1.3; }

    // avoid friendly stacking
    for (const a of this.units) {
      if (a === u || !a.alive || a.team !== u.team) continue;
      const d = Math.hypot(a.x - u.x, a.y - u.y);
      if (d < 78 && d > 0.01) {
        mx += (u.x - a.x) / d * (1 - d / 78) * 1.4;
        my += (u.y - a.y) / d * (1 - d / 78) * 1.4;
      }
    }

    // avoid enemy lava
    for (const p of this.pools) {
      if (p.team === u.team || p.life < 0.4) continue;
      const d = Math.hypot(u.x - p.x, (u.y - p.y) / 0.6);
      if (d < p.r + 50) {
        const push = (1 - d / (p.r + 50)) * 2.6;
        mx += (u.x - p.x) / (d || 1) * push;
        my += ((u.y - p.y) / 0.6) / (d || 1) * push;
      }
    }

    // stay off the walls
    const m = 215;
    if (u.x < WORLD.left + m) mx += (1 - (u.x - WORLD.left) / m) * 1.8;
    if (u.x > WORLD.right - m) mx -= (1 - (WORLD.right - u.x) / m) * 1.8;
    if (u.y < WORLD.top + m) my += (1 - (u.y - WORLD.top) / m) * 1.8;
    if (u.y > WORLD.bottom - m) my -= (1 - (WORLD.bottom - u.y) / m) * 1.8;

    const ml = Math.hypot(mx, my);
    if (ml > 1) { mx /= ml; my /= ml; }

    // aim prediction with personality wobble
    const tt = dist / role.projSpeed;
    const lead = u.role === 'sniper' ? 0.93 : 0.78;
    const px = target.x + target.vx * tt * lead + target.kx * tt * 0.6;
    const py = target.y + target.vy * tt * lead + target.ky * tt * 0.6;
    const wobble = Math.sin(this.t * 1.7 + u.seed * 2) * (u.role === 'sniper' ? 0.03 : 0.05)
      + Math.sin(this.t * 0.7 + u.seed) * 0.02;
    const aim = Math.atan2(py - u.y, px - u.x) + wobble;
    u.aim = angLerp(u.aim, aim, Math.min(1, dt * 9));

    // dodge incoming
    if (u.dashCd <= 0 && Math.random() < dt * 2.2) {
      for (const p of this.projectiles) {
        if (p.team === u.team) continue;
        const pd = Math.hypot(p.x - u.x, p.y - u.y);
        if (pd < 175 && pd > 20) {
          const approach = (p.vx * (u.x - p.x) + p.vy * (u.y - p.y)) / pd;
          if (approach > 140) {
            const side = Math.random() < 0.5 ? 1 : -1;
            this.doDash(u, -p.vy / Math.hypot(p.vx, p.vy) * side, p.vx / Math.hypot(p.vx, p.vy) * side);
            break;
          }
        }
      }
    }

    if (u.dashT <= 0) {
      const slow = u.slowT > 0 ? 0.72 : 1;
      const k = Math.min(1, dt * 11);
      u.vx += (mx * u.speed * slow - u.vx) * k;
      u.vy += (my * u.speed * slow - u.vy) * k;
    }

    // fire
    const inRange = dist < role.range * 0.92;
    if (inRange && u.cooldown <= 0) {
      const facing = Math.abs(((u.aim - Math.atan2(target.y - u.y, target.x - u.x) + Math.PI * 3) % TAU) - Math.PI);
      if (facing < 0.35) this.firePrimary(u, u.aim);
    }

    // special
    if (u.specialCd <= 0) {
      if (u.role === 'brawler' && dist < 390) this.doSpecial(u);
      else if (u.role === 'sniper' && dist < 690 && dist > 260) this.doSpecial(u);
    }
  }

  nearestEnemy(u, maxDist = 9999) {
    let best = null, bd = maxDist * maxDist;
    for (const e of this.units) {
      if (!e.alive || e.team === u.team) continue;
      const d = dist2(u.x, u.y, e.x, e.y);
      if (d < bd) { bd = d; best = e; }
    }
    return best;
  }

  doDash(u, mx, my) {
    let dx = mx, dy = my;
    if (Math.hypot(dx, dy) < 0.1) { dx = Math.cos(u.aim); dy = Math.sin(u.aim); }
    const l = Math.hypot(dx, dy) || 1;
    u.dashDirX = dx / l; u.dashDirY = dy / l;
    u.dashT = 0.17;
    u.dashCd = ROLE[u.role].dashCd;
    this.burst(u.x, u.y, 8, { colors: [TEAM[u.team].color, '#e9ffce'], speed: [40, 160], size: [2, 5], life: [0.2, 0.45], kind: 'ember', gravity: -20, spread: Math.PI * 2 });
    if (u.isPlayer) { Sfx.dash(); this.shakeBy(2.2); }
  }

  doSpecial(u) {
    const role = ROLE[u.role];
    if (u.specialCd > 0) return;
    u.specialCd = role.specialCd;
    if (u.role === 'brawler') {
      // lava egg fan
      for (let i = -2; i <= 2; i++) {
        this.spawnEgg(u, u.aim + i * 0.17, { damage: role.damage * 0.78, speed: 630, poolR: role.poolRadius * 0.85 });
      }
      this.burst(u.x + Math.cos(u.aim) * 40, u.y + Math.sin(u.aim) * 40, 18, {
        colors: ['#7dff3c', '#b6ff7a', '#ffb347'], speed: [50, 230], size: [2, 5], life: [0.3, 0.7], kind: 'goo', gravity: 130, spread: 1.4, dir: u.aim
      });
      if (u.isPlayer) { Sfx.egg(); this.shakeBy(4); }
    } else {
      // piercing lava beam
      const range = 900;
      const ex = u.x + Math.cos(u.aim) * range;
      const ey = u.y + Math.sin(u.aim) * range;
      const mx = u.x + Math.cos(u.aim) * 44;
      const my = u.y + Math.sin(u.aim) * 44;
      this.beams.push({ x1: mx, y1: my, x2: ex, y2: ey, life: 0.38, maxLife: 0.38, width: 26, team: u.team });
      this.spawnShock(mx, my, 100, TEAM[u.team].color, 0.4);
      let hitAny = false;
      for (const e of this.units) {
        if (!e.alive || e.team === u.team) continue;
        const t = clamp(((e.x - u.x) * Math.cos(u.aim) + (e.y - u.y) * Math.sin(u.aim)) / range, 0, 1);
        const cx = u.x + Math.cos(u.aim) * range * t;
        const cy = u.y + Math.sin(u.aim) * range * t;
        if (Math.hypot(e.x - cx, e.y - cy) < e.r + 30) {
          this.damage(e, 46, u, { knock: 260, dirX: Math.cos(u.aim), dirY: Math.sin(u.aim) });
          e.burnT = Math.max(e.burnT, 2.2);
          e.burnDps = 12;
          e.burnFrom = u;
          hitAny = true;
          this.burst(e.x, e.y, 16, { colors: ['#7dff3c', '#e9ffce', '#ffd166'], speed: [50, 240], size: [2, 5], life: [0.25, 0.6], kind: 'goo', gravity: 120, spread: 1.5 });
        }
      }
      if (hitAny) this.shakeBy(6);
      Sfx.beam();
      if (u.isPlayer) this.shakeBy(9);
    }
    if (Math.random() < 0.5) this.spawnFloat(u.x, u.y - 160, u.role === 'brawler' ? '¡LLUVIA DE LAVA!' : '¡PLUMA PENETRANTE!', u.role === 'brawler' ? '#7dff3c' : '#ffd166', 12);
  }

  spawnEgg(u, angle, opts = {}) {
    const role = ROLE[u.role];
    const speed = opts.speed || role.projSpeed;
    const range = opts.range || role.range;
    const mx = u.x + Math.cos(angle) * 38;
    const my = u.y + Math.sin(angle) * 38;
    this.projectiles.push({
      kind: 'egg', team: u.team, owner: u,
      x: mx, y: my, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
      angle, life: range / speed, maxLife: range / speed, age: 0,
      z: 0, spin: rand(0, TAU), seed: rand(0, 10), radius: 12,
      damage: opts.damage || role.damage, poolR: opts.poolR || role.poolRadius,
      trail: 0
    });
  }

  spawnPlume(u, angle) {
    const role = ROLE[u.role];
    const mx = u.x + Math.cos(angle) * 42;
    const my = u.y + Math.sin(angle) * 42;
    this.projectiles.push({
      kind: 'plume', team: u.team, owner: u,
      x: mx, y: my, vx: Math.cos(angle) * role.projSpeed, vy: Math.sin(angle) * role.projSpeed,
      angle, life: role.range / role.projSpeed, maxLife: role.range / role.projSpeed, age: 0,
      z: 0, radius: 11, damage: role.damage, pierce: role.pierce,
      hit: new Set(), trail: 0
    });
  }

  firePrimary(u, angle) {
    if (!u.alive || u.cooldown > 0) return;
    const role = ROLE[u.role];
    u.cooldown = role.fireDelay;
    u.flash = 0.07;
    if (u.role === 'brawler') {
      this.spawnEgg(u, angle);
      Sfx.egg();
      this.burst(u.x + Math.cos(angle) * 42, u.y + Math.sin(angle) * 42, 5, {
        colors: ['#7dff3c', '#b6ff7a'], speed: [20, 100], size: [1.2, 2.6], life: [0.15, 0.35], kind: 'goo', gravity: 80, spread: 0.8, dir: angle
      });
    } else {
      this.spawnPlume(u, angle);
      Sfx.plume();
      this.burst(u.x + Math.cos(angle) * 44, u.y + Math.sin(angle) * 44, 4, {
        colors: ['#e9ffce', '#7dff3c', '#ffd166'], speed: [40, 150], size: [1, 2.6], life: [0.12, 0.3], kind: 'ember', gravity: 0, spread: 0.5, dir: angle
      });
    }
  }

  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.age += dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.kind === 'egg') {
        const prog = 1 - Math.max(0, p.life) / p.maxLife;
        p.z = Math.sin(prog * Math.PI) * 34;
        p.spin += dt * 7;
        p.trail -= dt;
        if (p.trail <= 0) {
          p.trail = 0.03;
          this.spawnParticle({
            x: p.x + rand(-4, 4), y: p.y - 46 - p.z, vx: rand(-12, 12), vy: rand(-4, 18),
            life: rand(0.16, 0.35), maxLife: 0.35, size: rand(1, 2.4), color: Math.random() < 0.7 ? '#7dff3c' : '#d8ffb0',
            kind: 'goo', gravity: 20, rot: 0, vr: 0, drag: 0.9
          });
        }
      } else {
        p.trail -= dt;
        if (p.trail <= 0) {
          p.trail = 0.028;
          this.spawnParticle({
            x: p.x - (p.vx * 0.012), y: p.y - 46, vx: rand(-10, 10), vy: rand(-10, 10),
            life: rand(0.14, 0.3), maxLife: 0.3, size: rand(1, 2.2), color: Math.random() < 0.6 ? '#7dff3c' : '#e9ffce',
            kind: 'ember', gravity: 0, rot: 0, vr: 0, drag: 0.88
          });
        }
      }

      if (p.life <= 0) {
        if (p.kind === 'egg') this.splatEgg(p);
        this.projectiles.splice(i, 1);
        continue;
      }
      if (p.x < WORLD.left - 80 || p.x > WORLD.right + 80 || p.y < WORLD.top - 80 || p.y > WORLD.bottom + 80) {
        if (p.kind === 'egg') this.splatEgg(p);
        this.projectiles.splice(i, 1);
        continue;
      }

      let remove = false;
      for (const u of this.units) {
        if (!u.alive || u.team === p.team) continue;
        if (p.hit && p.hit.has(u)) continue;
        if (dist2(p.x, p.y, u.x, u.y) > (p.radius + u.r) * (p.radius + u.r)) continue;

        if (p.kind === 'egg') {
          this.damage(u, p.damage, p.owner, { knock: 110, dirX: p.vx / Math.hypot(p.vx, p.vy), dirY: p.vy / Math.hypot(p.vx, p.vy) });
          // splash on nearby enemies
          for (const o of this.units) {
            if (o === u || !o.alive || o.team === p.team) continue;
            if (dist2(p.x, p.y, o.x, o.y) < 74 * 74) {
              this.damage(o, 12, p.owner, { knock: 60, dirX: (o.x - p.x) / 70, dirY: (o.y - p.y) / 70 });
            }
          }
          this.splatEgg(p);
          remove = true;
          break;
        } else {
          this.damage(u, p.damage, p.owner, { knock: 120, dirX: p.vx / Math.hypot(p.vx, p.vy), dirY: p.vy / Math.hypot(p.vx, p.vy) });
          if (u.alive) {
            u.burnT = Math.max(u.burnT, ROLE.sniper.burnTime);
            u.burnDps = ROLE.sniper.burnDps;
            u.burnFrom = p.owner;
          }
          p.hit.add(u);
          p.pierce -= 1;
          this.burst(p.x, p.y, 6, { colors: ['#7dff3c', '#e9ffce'], speed: [30, 120], size: [1, 2.6], life: [0.15, 0.35], kind: 'ember', gravity: 0 });
          if (p.pierce < 0) { remove = true; break; }
        }
      }
      if (remove) this.projectiles.splice(i, 1);
    }
  }

  splatEgg(p) {
    const owner = p.owner;
    const r = p.poolR || 62;
    this.pools.push({
      x: p.x, y: p.y, r, life: ROLE.brawler.poolLife, maxLife: ROLE.brawler.poolLife,
      team: p.team, dps: ROLE.brawler.poolDps, owner, seed: rand(0, 100)
    });
    this.spawnShock(p.x, p.y, r * 1.4, '#7dff3c', 0.42);
    this.burst(p.x, p.y, 20, { colors: ['#7dff3c', '#b6ff7a', '#2f6b32', '#0b0f0b'], speed: [40, 210], size: [2, 5], life: [0.3, 0.7], kind: 'goo', gravity: 150, spread: Math.PI * 2 });
    this.burst(p.x, p.y, 6, { colors: ['#1a1e18', '#3c4540'], speed: [10, 60], size: [5, 10], life: [0.35, 0.7], kind: 'smoke', gravity: -20, spread: Math.PI * 2 });
    Sfx.splat();
    if (this.player) {
      const d = Math.hypot(this.player.x - p.x, this.player.y - p.y);
      if (d < 260) this.shakeBy(2 + (1 - d / 260) * 3);
    }
  }

  updatePools(dt) {
    for (let i = this.pools.length - 1; i >= 0; i--) {
      const pool = this.pools[i];
      pool.life -= dt;
      if (pool.life <= 0) { this.pools.splice(i, 1); continue; }
      for (const u of this.units) {
        if (!u.alive || u.team === pool.team) continue;
        const nx = (u.x - pool.x) / pool.r;
        const ny = (u.y - pool.y) / (pool.r * 0.62);
        if (nx * nx + ny * ny < 1) {
          u.slowT = 0.1;
          this.damage(u, pool.dps * dt, pool.owner, { silent: true, burn: true });
          u.poolAcc = (u.poolAcc || 0) + pool.dps * dt;
          if (u.poolAcc > 14) {
            u.poolAcc = 0;
            this.spawnFloat(u.x, u.y - 120, `-${Math.round(14)}`, '#8dff5c', 11);
          }
          if (Math.random() < dt * 8) {
            this.spawnParticle({
              x: u.x + rand(-14, 14), y: u.y - rand(20, 90), vx: rand(-10, 10), vy: -rand(15, 50),
              life: rand(0.2, 0.5), maxLife: 0.5, size: rand(1.5, 3), color: '#7dff3c',
              kind: 'ember', gravity: -20, rot: 0, vr: 0, drag: 0.9
            });
          }
        }
      }
    }
  }

  damage(u, amount, source, opts = {}) {
    if (!u.alive || u.invuln > 0 || amount <= 0) return;
    u.hp -= amount;
    u.hitFlash = Math.max(u.hitFlash, opts.silent ? 0.04 : 0.16);
    if (!opts.silent) {
      if (opts.knock && source) {
        u.kx += (opts.dirX || 0) * opts.knock;
        u.ky += (opts.dirY || 0) * opts.knock;
      }
      this.burst(u.x, u.y, 3, { colors: ['#ffd166', '#7dff3c', '#ffe9b8'], speed: [30, 130], size: [1, 2.6], life: [0.15, 0.35], kind: 'ember', gravity: 120 });
      if (amount >= 8) this.spawnFloat(u.x, u.y - 132, String(Math.round(amount)), source && source.team === 0 ? '#fff1c9' : '#ffb3a0', 14);
      Sfx.hit();
      if (u.isPlayer) this.shakeBy(4);
    }
    if (u.hp <= 0) this.kill(u, source);
  }

  kill(u, killer) {
    if (!u.alive) return;
    u.alive = false;
    u.hp = 0;
    u.respawn = 4.4;
    u.burnT = 0;
    u.deathX = u.x; u.deathY = u.y;
    this.burst(u.x, u.y, 26, { colors: [u.def.palette.feather, u.def.palette.featherDark, '#7dff3c', '#ffd166'], speed: [60, 260], size: [2, 5], life: [0.5, 1.2], kind: 'feather', gravity: 260, spread: Math.PI * 2 });
    this.burst(u.x, u.y, 14, { colors: ['#7dff3c', '#2f6b32', '#0b0f0b'], speed: [40, 190], size: [2, 5], life: [0.3, 0.8], kind: 'goo', gravity: 200, spread: Math.PI * 2 });
    this.spawnShock(u.x, u.y, 90, TEAM[u.team].color, 0.55);
    Sfx.kill();
    this.shakeBy(u.isPlayer ? 13 : 5);

    if (killer && killer.team !== u.team) {
      if (this.state !== 'attract') this.scores[killer.team] += 1;
      killer.streak = (killer.streak || 0) + 1;
    }
    const atkName = killer ? killer.def.name : 'LAVA';
    this.feed.unshift({ a: atkName, b: u.def.name, team: killer ? killer.team : u.team, life: 5 });
    if (this.feed.length > 4) this.feed.length = 4;

    if (this.state === 'attract') return;

    if (!this.firstBlood) {
      this.firstBlood = true;
      this.announce = { text: '¡PRIMERA SANGRE!', sub: `${atkName} abrió la veta`, life: 1.7, maxLife: 1.7, color: '#ffd166' };
    } else if (killer && killer.isPlayer) {
      this.announce = { text: '¡BAJA!', sub: killer.streak > 1 ? `Racha de ${killer.streak}` : 'Bien cocinado', life: 1.3, maxLife: 1.3, color: '#b6ff7a' };
    } else if (u.isPlayer) {
      this.announce = { text: '¡TE DERRIBARON!', sub: `Vuelves en 4 segundos`, life: 1.9, maxLife: 1.9, color: '#ff7a6a' };
    } else if (killer && killer.team === 0 && killer.streak === 3) {
      this.announce = { text: `¡RACHA DE ${killer.def.name}!`, sub: 'Tres plumas al aire', life: 1.6, maxLife: 1.6, color: '#7dff3c' };
    }

    if (this.scores[0] >= 10 || this.scores[1] >= 10) {
      this.endRound();
    }
  }

  respawn(u) {
    u.alive = true;
    u.hp = u.maxHp;
    u.x = u.spawnX; u.y = u.spawnY;
    u.vx = 0; u.vy = 0; u.kx = 0; u.ky = 0;
    u.invuln = 1.6;
    u.respawn = 0;
    u.burnT = 0;
    u.cooldown = 0.35;
    u.dashCd = 0;
    u.specialCd = Math.min(u.specialCd, 2);
    u.aim = u.team === 0 ? 0 : Math.PI;
    u.target = null;
    u.streak = 0;
    this.spawnShock(u.x, u.y, 90, TEAM[u.team].color, 0.6);
    this.burst(u.x, u.y, 12, { colors: [TEAM[u.team].color, '#e9ffce'], speed: [20, 120], size: [1.5, 4], life: [0.3, 0.6], kind: 'ember', gravity: -40, spread: Math.PI * 2 });
    if (u.isPlayer) { Sfx.respawn(); this.announce = { text: '¡DE VUELTA AL RUEDO!', sub: 'A romper huevos', life: 1.2, maxLife: 1.2, color: TEAM[0].color }; }
  }

  endRound() {
    if (this.state !== 'playing') return;
    const blue = this.scores[0], red = this.scores[1];
    const winner = blue > red ? 0 : red > blue ? 1 : -1;
    this.result = { winner, blue, red };
    this.state = 'over';
    this.shakeBy(14);
    if (winner === 0) Sfx.win(); else if (winner === 1) Sfx.lose(); else Sfx.ui();
    if (this.onEnd) this.onEnd(this.result);
  }

  /* ------------------------------------------------------------------ */
  drawWorld(ctx, t) {
    drawArena(ctx, t);
    for (const pool of this.pools) drawPool(ctx, pool, t);

    const sorted = this.units.filter(u => u.alive).sort((a, b) => a.y - b.y);
    for (const u of sorted) drawChampion(ctx, u, t, {});

    for (const p of this.projectiles) drawProjectile(ctx, p, t);
    for (const p of this.particles) drawParticle(ctx, p);
    for (const b of this.beams) drawBeam(ctx, b);
    for (const s of this.shocks) drawShockwave(ctx, s);
    for (const f of this.floats) drawFloatText(ctx, f);
  }
}

content.text:
Now main.js. Need careful wiring.

Menu card portraits: import drawChampion, create dummy using FIGHTERS[i] and ROLE. Canvas width/height 240x210? CSS aspect ratio. draw with translate.

Let's set canvas 260x230, draw at (130, 214) scale 1.62. Sniper rifle extends up to 48+ in aim direction; aim = 0.08 mostly right, within 260? hand x = 130 + ... scaled; rifle tip ~ x 130 + (17+36+... 48) *1.62 ≈ 130+163=293 > 260. Reduce scale to 1.35 and aim angle 0.55 (diagonal up-right) to fit? Weapon length local from shoulder x 17 + hand 36 + 48 = 101 px *1.35 = 136; x start 130 → 266. Slight clip. Center character left a bit: translate x=105, aim = -0.25 (up-right) so rifle points up. Vertically head at -120*1.35=-162 from baseline 215 → 53; rifle near head. Fine. Use scale 1.3, x=112, baseline y=216, aim=-0.18. Tail extends left -50*1.3=-65 → x 47. Good. Egg hand right. Let's just draw with scale 1.25 and x=120.

Portrait background: radial glow in canvas via gradient + floor ring. Draw before champion. Use team color.

Portrait dummy fields: x,y,aim,def,team,vx=0,vy=0,walkPhase=0,seed,hp,maxHp,hitFlash=0,invuln=0,isPlayer=false,r. opts {portrait:true, bars:false, scale:1.25}.

Card HTML:
```
<button class="card brawler selected" data-index=0 aria-label="REX">
 <canvas class="portrait"></canvas>
 <span class="chip">CORTA</span>
 <span class="cname">REX</span>
 <span class="ctitle">EL DEMOLEDOR</span>
 <span class="rolebar"></span>
</button>
```
Actually button labels include name; accessibility good. aria-label "Elegir a REX, corta distancia".

Note auto-capture Play label: aria-label="Play" on #playBtn. Good.

Main logic:

```js
import {Game} from './game.js';
import {FIGHTERS, ROLE, TEAM, WORLD} from './roster.js';
import {drawChampion, drawHUD, drawVignette, drawPause, drawOffscreenMarkers, clamp, worldToScreen} from './render.js';
import {Sfx} from './audio.js';
```

DOM refs.

resize:
```js
function measure() {
 w=window.innerWidth; h=window.innerHeight; dpr=Math.min(2, window.devicePixelRatio||1);
 canvas.width=Math.round(w*dpr); canvas.height=...
 canvas.style.width=w+'px'; style.height...
 const cs=getComputedStyle(probe); insets={top:parseFloat(cs.paddingTop)||0,...}
 isTouchUI = window.matchMedia('(pointer: coarse)').matches || w < 800;
 layout = computeLayout();
}
```
`isTouchUI` also if navigator.maxTouchPoints > 0? Playwright desktop context maxTouchPoints=0; mobile capture viewport 390 → w<800 true. Good.

Camera:
```js
const camera={x:WORLD.cx,y:WORLD.cy,zoom:1,shakeX:0,shakeY:0};
let zoomInit=false;
function updateCamera(dt){
  const fitDesktop = w>=800 && !isTouchUI;
  let targetZoom, tx, ty;
  if (game.state==='attract') {
     targetZoom = fitDesktop ? Math.min(w/1740,h/1080) : clamp(Math.min(w,h)/640,0.5,1.05);
     tx=800; ty=500;
  } else if (fitDesktop) {
     targetZoom = Math.min(w/1740,h/1080); tx=800; ty=500;
  } else {
     targetZoom = clamp(Math.min(w,h)/560, 0.62, 1.05);
     const p=game.player;
     tx=p?p.x:800; ty=p?p.y:500;
     const vw=w/targetZoom, vh=h/targetZoom;
     tx = vw>=WORLD.w ? WORLD.cx : clamp(tx, vw/2, WORLD.w-vw/2);
     ty = vh>=WORLD.h ? WORLD.cy : clamp(ty, vh/2, WORLD.h-vh/2);
  }
  if(!zoomInit){camera.zoom=targetZoom; zoomInit=true;}
  camera.zoom += (targetZoom-camera.zoom)*Math.min(1,dt*5);
  camera.x += (tx-camera.x)*Math.min(1,dt*7);
  camera.y += ...
  // clamp after movement
  const halfW=w/(2*camera.zoom), halfH=h/(2*camera.zoom);
  if(halfW*2 < WORLD.w) camera.x=clamp(camera.x, halfW, WORLD.w-halfW); else camera.x=WORLD.cx;
  ...
  const sh=game.shake;
  camera.shakeX=(Math.random()*2-1)*sh; camera.shakeY=...
}
```
Attract on mobile: menu covers. fine.

But desktop fit uses h/1080: on 1440x900 → min(0.827,0.833)=0.827. Arena 1600*0.827=1323 wide; nice.

HUD layout uses w/h; computeLayout each resize.

Insets: parseFloat padding values; env only works if CSS var? probe with padding env should compute px in Chromium. Good.

Touch sticks:
```js
const sticks = { move:null, aim:null };
const queued = {dash:false, special:false};
const held = { mouse:false };
const pointerMap = new Map();
```
