function drawStick(ctx, base, state, label, color) {
  if (!base) return;
  const active = !!state;
  ctx.save();
  ctx.globalAlpha = active ? 0.72 : 0.34;
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(base.x, base.y, base.r, 0, TAU); ctx.stroke();
  ctx.fillStyle = 'rgba(5,9,9,0.25)';
  ctx.beginPath(); ctx.arc(base.x, base.y, base.r, 0, TAU); ctx.fill();
  if (active) {
    const dx = (state.x || 0) * base.r * 0.55;
    const dy = (state.y || 0) * base.r * 0.55;
    ctx.globalAlpha = 0.85;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(base.x + dx, base.y + dy, base.r * 0.34, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.25;
    ctx.beginPath(); ctx.arc(base.x + dx, base.y + dy, base.r * 0.52, 0, TAU); ctx.fill();
  } else {
    ctx.globalAlpha = 0.5;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(base.x, base.y, base.r * 0.28, 0, TAU); ctx.fill();
  }
  ctx.globalAlpha = 0.6;
  ctx.textAlign = 'center';
  ctx.font = '900 7px system-ui, sans-serif';
  ctx.fillStyle = '#e9dfca';
  ctx.fillText(label, base.x, base.y + base.r + 13);
  ctx.restore();
}

