142:   /* ------------------------------------------------------------------ */
143:   update(dt, input) {
144:     dt = Math.min(dt, 0.04);
145:     this.t += dt;
146:     this.shake *= Math.pow(0.0025, dt);
147:     this.updateEffects(dt);
148:     if (this.state === 'over') return;
149:     if (this.state === 'paused') return;
150:     if (this.state === 'attract') {
151:       this.timer -= dt;
152:       if (this.timer <= 0 || this.scores[0] >= 10 || this.scores[1] >= 10) { this.reset(true); return; }
153:     } else {
154:       this.roundTime += dt;
155:       this.timer -= dt;
156:       if (this.timer <= 0) { this.timer = 0; this.endRound(); return; }
157:     }
158: 
159:     for (const u of this.units) {
160:       if (!u.alive) {
161:         u.respawn -= dt;
162:         if (u.respawn <= 0) this.respawn(u);
163:         continue;
164:       }
165:       u.cooldown = Math.max(0, u.cooldown - dt);
166:       u.dashCd = Math.max(0, u.dashCd - dt);
167:       u.specialCd = Math.max(0, u.specialCd - dt);
168:       u.invuln = Math.max(0, u.invuln - dt);
169:       u.hitFlash = Math.max(0, u.hitFlash - dt);
170:       u.flash = Math.max(0, u.flash - dt);
171:       u.slowT = Math.max(0, u.slowT - dt);
172: 
173:       if (u.burnT > 0) {
174:         u.burnT -= dt;
175:         this.damage(u, u.burnDps * dt, u.burnFrom, { silent: true, burn: true });
176:         if (Math.random() < dt * 14) {
177:           this.spawnParticle({
178:             x: u.x + rand(-16, 16), y: u.y - rand(30, 100), vx: rand(-15, 15), vy: -rand(20, 60),
179:             life: rand(0.2, 0.5), maxLife: 0.5, size: rand(1.5, 3), color: Math.random() < 0.5 ? '#ffb347' : '#7dff3c',
180:             kind: 'ember', gravity: -30, rot: 0, vr: 0, drag: 0.95
181:           });
182:         }
183:         if (!u.alive) continue;
184:       }
185: 
186:       if (this.state === 'playing' && u.isPlayer) this.updatePlayer(u, dt, input);
187:       else this.updateAI(u, dt);
188: 
189:       // integrate
190:       if (u.dashT > 0) {
191:         u.dashT -= dt;
192:         const sp = 720;
193:         u.vx = u.dashDirX * sp;
194:         u.vy = u.dashDirY * sp;
195:         if (Math.random() < 0.6) this.spawnParticle({
196:           x: u.x, y: u.y - 30, vx: rand(-20, 20), vy: rand(-10, 30), life: 0.34, maxLife: 0.34,
197:           size: rand(6, 12), color: TEAM[u.team].color, kind: 'smoke', gravity: 0, rot: 0, vr: 0, drag: 0.9
198:         });
199:       }
200:       u.x += (u.vx + u.kx) * dt;
201:       u.y += (u.vy + u.ky) * dt;
202:       u.kx *= Math.pow(0.0009, dt);
203:       u.ky *= Math.pow(0.0009, dt);
204: 
205:       const minX = WORLD.left + u.r * 0.4, maxX = WORLD.right - u.r * 0.4;
206:       const minY = WORLD.top + u.r * 0.4, maxY = WORLD.bottom - u.r * 0.4;
207:       if (u.x < minX) { u.x = minX; u.vx = Math.abs(u.vx) * 0.2; u.kx = Math.abs(u.kx) * 0.2; }
208:       if (u.x > maxX) { u.x = maxX; u.vx = -Math.abs(u.vx) * 0.2; u.kx = -Math.abs(u.kx) * 0.2; }
209:       if (u.y < minY) { u.y = minY; u.vy = Math.abs(u.vy) * 0.2; u.ky = Math.abs(u.ky) * 0.2; }
210:       if (u.y > maxY) { u.y = maxY; u.vy = -Math.abs(u.vy) * 0.2; u.ky = -Math.abs(u.ky) * 0.2; }
211: 
212:       const spd = Math.hypot(u.vx, u.vy);
213:       if (spd > 25) u.walkPhase += dt * (4 + spd * 0.035);
214:       else u.walkPhase += dt * 1.2;
215:       u.lastX = u.x; u.lastY = u.y;
216:     }
217: 
218:     this.updateProjectiles(dt);
219:     this.updatePools(dt);
220:   }
221: 
222:   updateEffects(dt) {
223:     this.feed = this.feed.filter(f => (f.life -= dt) > 0);
224:     if (this.announce) {
225:       this.announce.life -= dt;
226:       if (this.announce.life <= 0) this.announce = null;
227:     }
228:     for (let i = this.particles.length - 1; i >= 0; i--) {
229:       const p = this.particles[i];
230:       p.life -= dt;
231:       if (p.life <= 0) { this.particles.splice(i, 1); continue; }
232:       p.vy += (p.gravity || 0) * dt;
233:       p.x += p.vx * dt;
234:       p.y += p.vy * dt;
235:       p.vx *= Math.pow(p.drag ?? 0.95, dt * 60);
236:       p.rot += (p.vr || 0) * dt;
237:       if (p.kind === 'feather' || p.kind === 'smoke') p.vy *= Math.pow(0.55, dt * 8);
238:     }
239:     for (let i = this.floats.length - 1; i >= 0; i--) {
240:       const f = this.floats[i];
241:       f.life -= dt;
242:       f.y -= dt * 34;
243:       if (f.life <= 0) this.floats.splice(i, 1);
244:     }
245:     for (let i = this.beams.length - 1; i >= 0; i--) {
246:       this.beams[i].life -= dt;
247:       if (this.beams[i].life <= 0) this.beams.splice(i, 1);
248:     }
249:     for (let i = this.shocks.length - 1; i >= 0; i--) {
250:       const s = this.shocks[i];
251:       s.life -= dt;
252:       s.r += (s.maxR - s.r) * Math.min(1, dt * 10);
253:       if (s.life <= 0) this.shocks.splice(i, 1);
254:     }
255:   }
