257:   /* ------------------------------------------------------------------ */
258:   updatePlayer(u, dt, input) {
259:     if (!u.alive) return;
260:     let mx = input.moveX || 0, my = input.moveY || 0;
261:     const ml = Math.hypot(mx, my);
262:     if (ml > 1) { mx /= ml; my /= ml; }
263: 
264:     if (input.dash && u.dashCd <= 0) this.doDash(u, mx, my);
265:     if (input.special && u.specialCd <= 0) this.doSpecial(u);
266: 
267:     // Aim
268:     let aimAngle = null;
269:     if (input.hasAim) {
270:       aimAngle = Math.atan2(input.aimY - u.y, input.aimX - u.x);
271:     } else {
272:       const target = this.nearestEnemy(u, 1200);
273:       if (target) {
274:         const role = ROLE[u.role];
275:         const tt = Math.hypot(target.x - u.x, target.y - u.y) / role.projSpeed;
276:         aimAngle = Math.atan2(target.y + target.vy * tt * 0.7 - u.y, target.x + target.vx * tt * 0.7 - u.x);
277:       }
278:     }
279:     if (aimAngle !== null) u.aim = aimAngle;
280: 
281:     if (u.dashT <= 0) {
282:       const slow = u.slowT > 0 ? 0.72 : 1;
283:       const k = Math.min(1, dt * 13);
284:       u.vx += (mx * u.speed * slow - u.vx) * k;
285:       u.vy += (my * u.speed * slow - u.vy) * k;
286:       if (ml < 0.05) {
287:         u.vx *= Math.pow(0.001, dt);
288:         u.vy *= Math.pow(0.001, dt);
289:       }
290:     }
291: 
292:     if (input.firing && u.cooldown <= 0) {
293:       this.firePrimary(u, u.aim);
294:     }
295:   }
296: 
297:   updateAI(u, dt) {
298:     u.retarget -= dt;
299:     let target = u.target;
300:     if (!target || !target.alive || u.retarget <= 0) {
301:       target = this.nearestEnemy(u, 2400);
302:       u.target = target;
303:       u.retarget = rand(1.1, 2.2);
304:       if (Math.random() < 0.45) u.strafeDir *= -1;
305:     }
306:     if (!target) return;
307: 
308:     const role = ROLE[u.role];
309:     const dx = target.x - u.x, dy = target.y - u.y;
310:     const dist = Math.hypot(dx, dy) || 1;
311:     const nx = dx / dist, ny = dy / dist;
312:     const pref = role.preferred;
313:     let mx = 0, my = 0;
314: 
315:     if (dist > pref + 65) { mx += nx; my += ny; }
316:     else if (dist < pref - 90) { mx -= nx; my -= ny; }
317:     else {
318:       mx += -ny * u.strafeDir;
319:       my += nx * u.strafeDir;
320:       if (Math.random() < dt * 0.5) u.strafeDir *= -1;
321:     }
322: 
323:     // keep distance if sniper and enemy too close
324:     if (u.role === 'sniper' && dist < 240) { mx -= nx * 1.3; my -= ny * 1.3; }
325: 
326:     // avoid friendly stacking
327:     for (const a of this.units) {
328:       if (a === u || !a.alive || a.team !== u.team) continue;
329:       const d = Math.hypot(a.x - u.x, a.y - u.y);
330:       if (d < 78 && d > 0.01) {
331:         mx += (u.x - a.x) / d * (1 - d / 78) * 1.4;
332:         my += (u.y - a.y) / d * (1 - d / 78) * 1.4;
333:       }
334:     }
335: 
336:     // avoid enemy lava
337:     for (const p of this.pools) {
338:       if (p.team === u.team || p.life < 0.4) continue;
339:       const d = Math.hypot(u.x - p.x, (u.y - p.y) / 0.6);
340:       if (d < p.r + 50) {
341:         const push = (1 - d / (p.r + 50)) * 2.6;
342:         mx += (u.x - p.x) / (d || 1) * push;
343:         my += ((u.y - p.y) / 0.6) / (d || 1) * push;
344:       }
345:     }
346: 
347:     // stay off the walls
348:     const m = 215;
349:     if (u.x < WORLD.left + m) mx += (1 - (u.x - WORLD.left) / m) * 1.8;
350:     if (u.x > WORLD.right - m) mx -= (1 - (WORLD.right - u.x) / m) * 1.8;
351:     if (u.y < WORLD.top + m) my += (1 - (u.y - WORLD.top) / m) * 1.8;
352:     if (u.y > WORLD.bottom - m) my -= (1 - (WORLD.bottom - u.y) / m) * 1.8;
353: 
354:     const ml = Math.hypot(mx, my);
355:     if (ml > 1) { mx /= ml; my /= ml; }
356: 
357:     // aim prediction with personality wobble
358:     const tt = dist / role.projSpeed;
359:     const lead = u.role === 'sniper' ? 0.93 : 0.78;
360:     const px = target.x + target.vx * tt * lead + target.kx * tt * 0.6;
361:     const py = target.y + target.vy * tt * lead + target.ky * tt * 0.6;
362:     const wobble = Math.sin(this.t * 1.7 + u.seed * 2) * (u.role === 'sniper' ? 0.022 : 0.035)
363:       + Math.sin(this.t * 0.7 + u.seed) * 0.02;
364:     const aim = Math.atan2(py - u.y, px - u.x) + wobble;
365:     u.aim = angLerp(u.aim, aim, Math.min(1, dt * 9));
366: 
367:     // dodge incoming
368:     if (u.dashCd <= 0 && Math.random() < dt * 1.4) {
369:       for (const p of this.projectiles) {
370:         if (p.team === u.team) continue;
371:         const pd = Math.hypot(p.x - u.x, p.y - u.y);
372:         if (pd < 175 && pd > 20) {
373:           const approach = (p.vx * (u.x - p.x) + p.vy * (u.y - p.y)) / pd;
374:           if (approach > 140) {
375:             const side = Math.random() < 0.5 ? 1 : -1;
376:             this.doDash(u, -p.vy / Math.hypot(p.vx, p.vy) * side, p.vx / Math.hypot(p.vx, p.vy) * side);
377:             break;
378:           }
379:         }
380:       }
381:     }
382: 
383:     if (u.dashT <= 0) {
384:       const slow = u.slowT > 0 ? 0.72 : 1;
385:       const k = Math.min(1, dt * 11);
386:       u.vx += (mx * u.speed * slow - u.vx) * k;
387:       u.vy += (my * u.speed * slow - u.vy) * k;
388:     }
389: 
390:     // fire
391:     const inRange = dist < role.range * 0.92;
392:     if (inRange && u.cooldown <= 0) {
393:       const facing = Math.abs(((u.aim - Math.atan2(target.y - u.y, target.x - u.x) + Math.PI * 3) % TAU) - Math.PI);
394:       if (facing < 0.35) this.firePrimary(u, u.aim);
395:     }
396: 
397:     // special
398:     if (u.specialCd <= 0) {
399:       if (u.role === 'brawler' && dist < 390) this.doSpecial(u);
400:       else if (u.role === 'sniper' && dist < 690 && dist > 260) this.doSpecial(u);
401:     }
402:   }
403: 
404:   nearestEnemy(u, maxDist = 9999) {
405:     let best = null, bd = maxDist * maxDist;
406:     for (const e of this.units) {
407:       if (!e.alive || e.team === u.team) continue;
408:       const d = dist2(u.x, u.y, e.x, e.y);
409:       if (d < bd) { bd = d; best = e; }
410:     }
411:     return best;
412:   }
413: 
414:   doDash(u, mx, my) {
415:     let dx = mx, dy = my;
416:     if (Math.hypot(dx, dy) < 0.1) { dx = Math.cos(u.aim); dy = Math.sin(u.aim); }
417:     const l = Math.hypot(dx, dy) || 1;
418:     u.dashDirX = dx / l; u.dashDirY = dy / l;
419:     u.dashT = 0.17;
420:     u.dashCd = ROLE[u.role].dashCd;
421:     this.burst(u.x, u.y, 8, { colors: [TEAM[u.team].color, '#e9ffce'], speed: [40, 160], size: [2, 5], life: [0.2, 0.45], kind: 'ember', gravity: -20, spread: Math.PI * 2 });
422:     if (u.isPlayer) { Sfx.dash(); this.shakeBy(2.2); }
423:   }
424: 
425:   doSpecial(u) {
426:     const role = ROLE[u.role];
427:     if (u.specialCd > 0) return;
428:     u.specialCd = role.specialCd;
429:     if (u.role === 'brawler') {
430:       // lava egg fan
431:       for (let i = -2; i <= 2; i++) {
432:         this.spawnEgg(u, u.aim + i * 0.17, { damage: role.damage * 0.78, speed: 630, poolR: role.poolRadius * 0.85 });
433:       }
434:       this.burst(u.x + Math.cos(u.aim) * 40, u.y + Math.sin(u.aim) * 40, 18, {
435:         colors: ['#7dff3c', '#b6ff7a', '#ffb347'], speed: [50, 230], size: [2, 5], life: [0.3, 0.7], kind: 'goo', gravity: 130, spread: 1.4, dir: u.aim
436:       });
437:       if (u.isPlayer) { Sfx.egg(); this.shakeBy(4); }
438:     } else {
439:       // piercing lava beam
440:       const range = 900;
441:       const ex = u.x + Math.cos(u.aim) * range;
442:       const ey = u.y + Math.sin(u.aim) * range;
443:       const mx = u.x + Math.cos(u.aim) * 44;
444:       const my = u.y + Math.sin(u.aim) * 44;
445:       this.beams.push({ x1: mx, y1: my, x2: ex, y2: ey, life: 0.38, maxLife: 0.38, width: 26, team: u.team });
446:       this.spawnShock(mx, my, 100, TEAM[u.team].color, 0.4);
447:       let hitAny = false;
448:       for (const e of this.units) {
449:         if (!e.alive || e.team === u.team) continue;
450:         const t = clamp(((e.x - u.x) * Math.cos(u.aim) + (e.y - u.y) * Math.sin(u.aim)) / range, 0, 1);
451:         const cx = u.x + Math.cos(u.aim) * range * t;
452:         const cy = u.y + Math.sin(u.aim) * range * t;
453:         if (Math.hypot(e.x - cx, e.y - cy) < e.r + 30) {
454:           this.damage(e, 46, u, { knock: 260, dirX: Math.cos(u.aim), dirY: Math.sin(u.aim) });
455:           e.burnT = Math.max(e.burnT, 2.2);
456:           e.burnDps = 12;
457:           e.burnFrom = u;
458:           hitAny = true;
459:           this.burst(e.x, e.y, 16, { colors: ['#7dff3c', '#e9ffce', '#ffd166'], speed: [50, 240], size: [2, 5], life: [0.25, 0.6], kind: 'goo', gravity: 120, spread: 1.5 });
460:         }
461:       }
462:       if (hitAny) this.shakeBy(6);
463:       Sfx.beam();
464:       if (u.isPlayer) this.shakeBy(9);
465:     }
466:     if (Math.random() < 0.5) this.spawnFloat(u.x, u.y - 160, u.role === 'brawler' ? '¡LLUVIA DE LAVA!' : '¡PLUMA PENETRANTE!', u.role === 'brawler' ? '#7dff3c' : '#ffd166', 12);
467:   }
