474:     const my = u.y + Math.sin(angle) * 38;
475:     this.projectiles.push({
476:       kind: 'egg', team: u.team, owner: u,
477:       x: mx, y: my, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
478:       angle, life: range / speed, maxLife: range / speed, age: 0,
479:       z: 0, spin: rand(0, TAU), seed: rand(0, 10), radius: 12,
480:       damage: opts.damage || role.damage, poolR: opts.poolR || role.poolRadius,
481:       trail: 0
482:     });
