  { name: 'now', bHp:190, sHp:155, bDmg:24, sDmg:32, bDelay:1.05, sDelay:0.95 },
  { name: 'A', bHp:220, sHp:180, bDmg:22, sDmg:28, bDelay:1.1, sDelay:1.0 },
  { name: 'B', bHp:210, sHp:170, bDmg:23, sDmg:30, bDelay:1.1, sDelay:1.0 },
  { name: 'C', bHp:240, sHp:195, bDmg:22, sDmg:28, bDelay:1.15, sDelay:1.05 },
  { name: 'D', bHp:220, sHp:180, bDmg:24, sDmg:32, bDelay:1.15, sDelay:1.05 },
];
const results = await page.evaluate(async (configs) => {
  const { ROLE } = await import('./js/roster.js');
  const g = window.__gallos.game;
  const input = {moveX:0.3,moveY:0.1,firing:true,hasAim:false,aimX:0,aimY:0};
  const out = {};
  for (const c of configs) {
    ROLE.brawler.hp=c.bHp; ROLE.sniper.hp=c.sHp;
    ROLE.brawler.damage=c.bDmg; ROLE.sniper.damage=c.sDmg;
    ROLE.brawler.fireDelay=c.bDelay; ROLE.sniper.fireDelay=c.sDelay;
    const times=[], totals=[];
    for (let run=0; run<6; run++) {
      g.start(run%4);
      let i=0;
