import { createRequire } from 'node:module';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
for (const vp of [{w:1440,h:900,name:'desktop'},{w:390,h:844,name:'mobile'}]) {
  const page = await browser.newPage({ viewport:{width:vp.w,height:vp.h}, isMobile:vp.name==='mobile', hasTouch:vp.name==='mobile', deviceScaleFactor:vp.name==='mobile'?2:1 });
  await page.goto('http://localhost:3002',{waitUntil:'load'});
  const measure = () => page.evaluate(() => new Promise(res => {
    let n=0; const t0=performance.now();
    function tick(){ n++; if(performance.now()-t0<2000) requestAnimationFrame(tick); else res(+(n/((performance.now()-t0)/1000)).toFixed(1)); }
    requestAnimationFrame(tick);
  }));
  const attract = await measure();
  await page.evaluate(()=>window.__gallos.start(0));
  const play = await measure();
  // no units/effects test
  const bare = await page.evaluate(()=>new Promise(res=>{
    const g=window.__gallos.game; g.units=[]; g.projectiles=[]; g.pools=[]; g.particles=[];
    let n=0; const t0=performance.now();
    function tick(){ n++; if(performance.now()-t0<1500) requestAnimationFrame(tick); else res(+(n/((performance.now()-t0)/1000)).toFixed(1)); }
    requestAnimationFrame(tick);
  }));
  console.log(vp.name, 'attract', attract, 'play', play, 'empty', bare);
  await page.close();
}
await browser.close();
EOF
